import { IoAdapter } from '@nestjs/platform-socket.io';
import { ServerOptions } from 'socket.io';
import { createAdapter } from '@socket.io/redis-adapter';
import { Redis } from 'ioredis';
import { INestApplication, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

export class RedisIoAdapter extends IoAdapter {
  private adapterConstructor: ReturnType<typeof createAdapter> | undefined;
  private readonly logger = new Logger(RedisIoAdapter.name);
  public isReady = false;

  constructor(private readonly app: INestApplication) {
    super(app);
  }

  async connectToRedis(): Promise<void> {
    const configService = this.app.get(ConfigService);
    const redisUrl =
      configService.get<string>('REDIS_URL') || 'redis://localhost:6379';

    try {
      const pubClient = new Redis(redisUrl, {
        maxRetriesPerRequest: 0,
        lazyConnect: true,
        enableOfflineQueue: false,
        connectTimeout: 3000,
      });
      const subClient = pubClient.duplicate();

      // Actually attempt the connection
      await Promise.all([pubClient.connect(), subClient.connect()]);

      pubClient.on('error', (err) =>
        this.logger.warn(`Redis pub error: ${err.message}`),
      );
      subClient.on('error', (err) =>
        this.logger.warn(`Redis sub error: ${err.message}`),
      );

      this.adapterConstructor = createAdapter(pubClient, subClient);
      this.isReady = true;
      this.logger.log('✅ Socket.IO Redis adapter connected');
    } catch (err: any) {
      this.logger.warn(
        `⚠️  Redis unavailable (${err.message ?? err}). Socket.IO will use the default in-process adapter.`,
      );
      this.isReady = false;
    }
  }

  createIOServer(port: number, options?: ServerOptions): any {
    const server = super.createIOServer(port, options);
    if (this.adapterConstructor) {
      server.adapter(this.adapterConstructor);
    }
    return server;
  }
}

import { Injectable } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';

@Injectable()
export class OptionalJwtAuthGuard extends AuthGuard('jwt') {
  handleRequest(
    _err: any,
    user: any,
    _info: any,
    _context: any,
    _status?: any,
  ) {
    // Return the user if authenticated, otherwise return undefined (do not throw error)
    return user;
  }
}

// src/modules/auth/auth.module.ts
import { Module } from '@nestjs/common';
import { JwtModule } from '@nestjs/jwt';
import { PassportModule } from '@nestjs/passport';
import { ConfigModule, ConfigService } from '@nestjs/config';
import { UsersModule } from '../users/users.module.js';
import { AuthController } from './auth.controller.js';
import { AuthService } from './auth.service.js';
import { JwtStrategy } from './strategies/jwt.strategy.js';
import { RefreshStrategy } from './strategies/refresh.strategy.js';

@Module({
  imports: [
    PassportModule.register({ defaultStrategy: 'jwt' }),
    JwtModule.registerAsync({
      imports: [ConfigModule],
      useFactory: (configService: ConfigService) => ({
        secret: configService.getOrThrow<string>('JWT_ACCESS_SECRET'),
        signOptions: {
          expiresIn: (configService.get<string>('JWT_ACCESS_EXPIRES') ??
            '15m') as any,
        },
      }),
      inject: [ConfigService],
    }),
    UsersModule,
  ],
  controllers: [AuthController],
  providers: [AuthService, JwtStrategy, RefreshStrategy],
  exports: [AuthService, JwtModule],
})
export class AuthModule {}

// src/modules/auth/auth.service.ts
import {
  BadRequestException,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { JwtService } from '@nestjs/jwt';
import { PasswordService } from '../../common/service/password.service.js';
import { UsersService } from '../users/users.service.js';
import { RegisterDto } from './dto/register.dto.js';
import { LoginDto } from './dto/login.dto.js';
import { RefreshTokenDto } from './dto/refresh-token.dto.js';
import { AuthResponseDto } from './dto/auth-response.dto.js';
import { AppRole } from '../../common/constants/roles.js';

@Injectable()
export class AuthService {
  constructor(
    private readonly usersService: UsersService,
    private readonly passwordService: PasswordService,
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
  ) {}

  async register(dto: RegisterDto): Promise<AuthResponseDto> {
    if (!dto.email && !dto.phoneNumber) {
      throw new BadRequestException(
        'Provide at least one of email or phone number',
      );
    }

    if (dto.email) {
      const emailExists = await this.usersService.findByEmail(dto.email);
      if (emailExists) {
        throw new BadRequestException('Email already registered');
      }
    }

    if (dto.phoneNumber) {
      const phoneExists = await this.usersService.findByPhoneNumber(
        dto.phoneNumber,
      );
      if (phoneExists) {
        throw new BadRequestException('Phone number already registered');
      }
    }

    if (dto.username) {
      const usernameExists = await this.usersService.findByUsername(
        dto.username,
      );
      if (usernameExists) {
        throw new BadRequestException('Username already taken');
      }
    }

    const defaultRole = await this.usersService.getRoleByName(AppRole.USER);
    if (!defaultRole) {
      throw new BadRequestException('Default USER role not found in system');
    }

    const passwordHash = await this.passwordService.hash(dto.password);

    const user = await this.usersService.create({
      email: dto.email,
      phoneNumber: dto.phoneNumber,
      username: dto.username,
      firstName: dto.firstName,
      lastName: dto.lastName,
      passwordHash,
      roleId: defaultRole.id,
    });

    const accessToken = await this.generateAccessToken(
      user.id,
      user.email ?? user.phoneNumber ?? user.username ?? 'user',
      user.role.name,
    );
    const refreshToken = await this.generateRefreshToken(user.id);

    const refreshHash = await this.passwordService.hash(refreshToken);
    const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

    await this.usersService.saveRefreshToken(
      user.id,
      refreshHash,
      refreshExpires,
    );
    await this.usersService.createSession({
      userId: user.id,
      expiresAt: refreshExpires,
    });

    return {
      user: {
        id: user.id,
        email: user.email,
        phoneNumber: user.phoneNumber,
        username: user.username,
        role: user.role.name,
      },
      accessToken,
      refreshToken,
    };
  }

  async login(dto: LoginDto): Promise<AuthResponseDto> {
    let user: Awaited<ReturnType<typeof this.usersService.findByEmail>>;

    if (dto.email) {
      user = await this.usersService.findByEmail(dto.email);
    } else if (dto.phoneNumber) {
      user = await this.usersService.findByPhoneNumber(dto.phoneNumber);
    } else if (dto.username) {
      user = await this.usersService.findByUsername(dto.username);
    }

    if (!user) {
      throw new UnauthorizedException('Invalid credentials');
    }

    if (user.status !== 'ACTIVE') {
      throw new UnauthorizedException(
        `Account is ${user.status.toLowerCase()}`,
      );
    }

    if (user.lockedUntil && user.lockedUntil > new Date()) {
      throw new UnauthorizedException(
        'Account is temporarily locked due to failed attempts',
      );
    }

    const isPasswordValid = await this.passwordService.compare(
      dto.password,
      user.passwordHash,
    );

    if (!isPasswordValid) {
      await this.usersService.incrementFailedLogin(user.id);
      throw new UnauthorizedException('Invalid credentials');
    }

    await this.usersService.updateLastLogin(user.id);

    const accessToken = await this.generateAccessToken(
      user.id,
      user.email ?? user.phoneNumber ?? user.username ?? 'user',
      user.role.name,
    );
    const refreshToken = await this.generateRefreshToken(user.id);

    await this.usersService.revokeRefreshTokens(user.id);

    const refreshHash = await this.passwordService.hash(refreshToken);
    const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

    await this.usersService.saveRefreshToken(
      user.id,
      refreshHash,
      refreshExpires,
    );
    await this.usersService.createSession({
      userId: user.id,
      expiresAt: refreshExpires,
    });

    return {
      user: {
        id: user.id,
        email: user.email,
        phoneNumber: user.phoneNumber,
        username: user.username,
        role: user.role.name,
      },
      accessToken,
      refreshToken,
    };
  }

  async refresh(
    dto: RefreshTokenDto,
  ): Promise<{ accessToken: string; refreshToken: string }> {
    if (!dto?.refreshToken) {
      throw new BadRequestException('Refresh token is required');
    }

    let payload: { sub: string };
    try {
      payload = await this.jwtService.verifyAsync<{ sub: string }>(
        dto.refreshToken,
        {
          secret: this.configService.getOrThrow<string>('JWT_REFRESH_SECRET'),
        },
      );
    } catch {
      throw new UnauthorizedException('Invalid or expired refresh token');
    }

    const user = await this.usersService.findById(payload.sub);
    if (!user || user.status !== 'ACTIVE') {
      throw new UnauthorizedException('User account invalid or inactive');
    }

    const activeToken = await this.usersService.findActiveRefreshToken(user.id);
    if (!activeToken) {
      throw new UnauthorizedException('Refresh token revoked or not found');
    }

    const matches = await this.passwordService.compare(
      dto.refreshToken,
      activeToken.tokenHash,
    );

    if (!matches) {
      // Security warning: possible token reuse attempt — revoke all user tokens
      await this.usersService.revokeRefreshTokens(user.id);
      throw new UnauthorizedException(
        'Invalid refresh token — all sessions revoked for security',
      );
    }

    await this.usersService.revokeRefreshTokens(user.id);

    const accessToken = await this.generateAccessToken(
      user.id,
      user.email ?? user.phoneNumber ?? user.username ?? 'user',
      user.role.name,
    );
    const newRefreshToken = await this.generateRefreshToken(user.id);

    const newRefreshHash = await this.passwordService.hash(newRefreshToken);
    const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

    await this.usersService.saveRefreshToken(
      user.id,
      newRefreshHash,
      refreshExpires,
    );

    return {
      accessToken,
      refreshToken: newRefreshToken,
    };
  }

  async logout(userId: string): Promise<{ message: string }> {
    await this.usersService.revokeRefreshTokens(userId);
    await this.usersService.revokeSessions(userId);
    return { message: 'Successfully logged out' };
  }

  private async generateAccessToken(
    userId: string,
    identifier: string,
    role: string,
  ): Promise<string> {
    const payload = { sub: userId, email: identifier, role };
    return this.jwtService.signAsync(payload, {
      secret: this.configService.getOrThrow<string>('JWT_ACCESS_SECRET'),
      expiresIn: (this.configService.get<string>('JWT_ACCESS_EXPIRES') ??
        '15m') as any,
    });
  }

  private async generateRefreshToken(userId: string): Promise<string> {
    const payload = { sub: userId };
    return this.jwtService.signAsync(payload, {
      secret: this.configService.getOrThrow<string>('JWT_REFRESH_SECRET'),
      expiresIn: (this.configService.get<string>('JWT_REFRESH_EXPIRES') ??
        '7d') as any,
    });
  }
}

// src/modules/channels/channels.service.ts
import {
  BadRequestException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { ChannelsRepository } from './channels.repository.js';
import { CreateChannelDto } from './dto/create-channel.dto.js';
import { UpdateChannelDto } from './dto/update-channel.dto.js';
import { ChannelResponseDto } from './dto/channel-response.dto.js';
import { GroupsRepository } from '../groups/groups.repository.js';

@Injectable()
export class ChannelsService {
  constructor(
    private readonly channelsRepository: ChannelsRepository,
    private readonly groupsRepository: GroupsRepository,
  ) {}

  async createChannel(
    groupId: string,
    dto: CreateChannelDto,
  ): Promise<ChannelResponseDto> {
    const group = await this.groupsRepository.findById(groupId);
    if (!group) {
      throw new NotFoundException('Group not found');
    }

    if (group.status !== 'ACTIVE') {
      throw new ForbiddenException('Group must be ACTIVE to create channels');
    }

    const existingSlug = await this.channelsRepository.findBySlug(
      groupId,
      dto.slug,
    );
    if (existingSlug) {
      throw new BadRequestException(
        `Channel with slug '${dto.slug}' already exists in this group`,
      );
    }

    const channel = await this.channelsRepository.createChannel(groupId, dto);
    return this.mapToDto(channel);
  }

  async getChannelsByGroup(
    groupId: string,
    userId: string,
  ): Promise<ChannelResponseDto[]> {
    const group = await this.groupsRepository.findById(groupId);
    if (!group) {
      throw new NotFoundException('Group not found');
    }

    const member = await this.groupsRepository.getMember(groupId, userId);
    // If not a group member, only show public channels
    const isMember = !!member;
    const channels = await this.channelsRepository.findByGroup(
      groupId,
      isMember ? undefined : false,
    );

    return channels.map((ch) => this.mapToDto(ch));
  }

  async getChannelById(
    channelId: string,
    userId: string,
  ): Promise<ChannelResponseDto> {
    const channel = await this.channelsRepository.findById(channelId);
    if (!channel) {
      throw new NotFoundException('Channel not found');
    }

    if (channel.isPrivate) {
      const member = await this.groupsRepository.getMember(
        channel.groupId,
        userId,
      );
      if (!member) {
        throw new ForbiddenException(
          'Private channel access requires group membership',
        );
      }
    }

    return this.mapToDto(channel);
  }

  async updateChannel(
    channelId: string,
    dto: UpdateChannelDto,
  ): Promise<ChannelResponseDto> {
    const channel = await this.channelsRepository.findById(channelId);
    if (!channel) {
      throw new NotFoundException('Channel not found');
    }

    const updated = await this.channelsRepository.updateChannel(channelId, dto);
    return this.mapToDto(updated);
  }

  async deleteChannel(channelId: string) {
    const channel = await this.channelsRepository.findById(channelId);
    if (!channel) {
      throw new NotFoundException('Channel not found');
    }

    await this.channelsRepository.softDeleteChannel(channelId);
    return { message: 'Channel deleted successfully' };
  }

  private mapToDto(channel: any): ChannelResponseDto {
    return {
      id: channel.id,
      groupId: channel.groupId,
      name: channel.name,
      slug: channel.slug,
      type: channel.type,
      description: channel.description,
      isPrivate: channel.isPrivate,
      conversationId:
        channel.conversations?.[0]?.id ?? channel.conversationId ?? null,
      createdAt: channel.createdAt,
    };
  }
}

// src/modules/comments/comments.service.ts
import {
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { CommentsRepository } from './comments.repository.js';
import { CreateCommentDto } from './dto/create-comment.dto.js';
import { CommentResponseDto } from './dto/comment-response.dto.js';
import { PostsRepository } from '../posts/posts.repository.js';

@Injectable()
export class CommentsService {
  constructor(
    private readonly commentsRepository: CommentsRepository,
    private readonly postsRepository: PostsRepository,
  ) {}

  async createComment(
    postId: string,
    authorId: string,
    dto: CreateCommentDto,
  ): Promise<CommentResponseDto> {
    const post = await this.postsRepository.findById(postId);
    if (!post) {
      throw new NotFoundException('Post not found');
    }

    if (dto.parentId) {
      const parent = await this.commentsRepository.findById(dto.parentId);
      if (!parent || parent.postId !== postId) {
        throw new NotFoundException('Parent comment not found for this post');
      }
    }

    const comment = await this.commentsRepository.createComment(
      postId,
      authorId,
      dto,
    );
    return this.mapToDto(comment);
  }

  async getCommentsByPost(postId: string, page = 1, limit = 20) {
    const post = await this.postsRepository.findById(postId);
    if (!post) {
      throw new NotFoundException('Post not found');
    }

    const skip = (page - 1) * limit;
    const { items, total } = await this.commentsRepository.findByPost(
      postId,
      skip,
      limit,
    );

    const data = items.map((c) => ({
      ...this.mapToDto(c),
      replies: (c.replies ?? []).map((r: any) => this.mapToDto(r)),
    }));

    return {
      data,
      meta: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
        hasNext: page * limit < total,
        hasPrev: page > 1,
      },
    };
  }

  async deleteComment(commentId: string, userId: string) {
    const comment = await this.commentsRepository.findById(commentId);
    if (!comment) {
      throw new NotFoundException('Comment not found');
    }

    if (comment.authorId !== userId) {
      throw new ForbiddenException('You can only delete your own comments');
    }

    await this.commentsRepository.softDelete(commentId, comment.postId);
    return { message: 'Comment deleted successfully' };
  }

  private mapToDto(c: any): CommentResponseDto {
    return {
      id: c.id,
      postId: c.postId,
      parentId: c.parentId,
      content: c.content,
      likesCount: c.likesCount ?? 0,
      author: {
        id: c.author.id,
        username: c.author.username,
        displayName: c.author.profile?.displayName ?? c.author.username,
        avatarUrl: c.author.profile?.avatar?.url ?? null,
      },
      createdAt: c.createdAt,
    };
  }
}

// src/modules/conversations/conversations.service.ts
import {
  BadRequestException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { ConversationsRepository } from './conversations.repository.js';
import { UsersRepository } from '../users/users.repository.js';
import { ConversationResponseDto } from './dto/conversation-response.dto.js';

@Injectable()
export class ConversationsService {
  constructor(
    private readonly conversationsRepository: ConversationsRepository,
    private readonly usersRepository: UsersRepository,
  ) {}

  async createDirectConversation(
    currentUserId: string,
    recipientId: string,
  ): Promise<ConversationResponseDto> {
    if (currentUserId === recipientId) {
      throw new BadRequestException(
        'You cannot start a direct chat with yourself',
      );
    }

    const recipient = await this.usersRepository.findById(recipientId);
    if (!recipient) {
      throw new NotFoundException('Recipient user not found');
    }

    const conversation = await this.conversationsRepository.findOrCreateDirect(
      currentUserId,
      recipientId,
    );
    return this.mapToDto(conversation, currentUserId);
  }

  async getUserConversations(
    userId: string,
  ): Promise<ConversationResponseDto[]> {
    const conversations =
      await this.conversationsRepository.getUserConversations(userId);
    return conversations.map((conv) => this.mapToDto(conv, userId));
  }

  async getConversationById(
    conversationId: string,
    userId: string,
  ): Promise<ConversationResponseDto> {
    const conversation =
      await this.conversationsRepository.findById(conversationId);
    if (!conversation) {
      throw new NotFoundException('Conversation not found');
    }

    return this.mapToDto(conversation, userId);
  }

  private mapToDto(conv: any, currentUserId: string): ConversationResponseDto {
    let title: string | null = null;

    if (conv.type === 'DIRECT') {
      const otherMember = conv.members?.find(
        (m: any) => m.userId !== currentUserId,
      );
      title =
        otherMember?.user?.profile?.displayName ??
        otherMember?.user?.username ??
        'Direct Chat';
    } else if (conv.channel?.name) {
      title = `#${conv.channel.name}`;
    }

    return {
      id: conv.id,
      type: conv.type,
      groupId: conv.groupId,
      channelId: conv.channelId,
      title,
      lastMessageAt: conv.lastMessageAt,
      members: (conv.members ?? []).map((m: any) => ({
        userId: m.user.id,
        username: m.user.username,
        displayName: m.user.profile?.displayName ?? m.user.username,
        avatarUrl: m.user.profile?.avatar?.url ?? null,
        unreadCount: m.unreadCount ?? 0,
        isMuted: m.isMuted ?? false,
      })),
      createdAt: conv.createdAt,
    };
  }
}

// src/modules/downloads/downloads.service.ts
import {
  BadRequestException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { PrismaService } from '../../prisma/prisma.service.js';
import { DownloadsRepository } from './downloads.repository.js';
import {
  RequestVideoDownloadDto,
  RequestFileDownloadDto,
} from './dto/request-download.dto.js';
import {
  DownloadPermission,
  VideoResolution,
  DownloadStatus,
} from '@prisma/client';
import { AppRole } from '../../common/constants/roles.js';
import crypto from 'crypto';
import path from 'path';

@Injectable()
export class DownloadsService {
  constructor(
    private readonly repo: DownloadsRepository,
    private readonly prisma: PrismaService,
    private readonly configService: ConfigService,
  ) {}

  /**
   * Authorize and generate a secure download link for a Video at chosen quality.
   */
  async authorizeVideoDownload(
    userId: string,
    dto: RequestVideoDownloadDto,
    ipAddress?: string,
    userAgent?: string,
  ) {
    const video = await this.prisma.video.findUnique({
      where: { id: dto.videoId, deletedAt: null },
      include: {
        videoChannel: {
          select: { id: true, groupId: true, downloadPermission: true },
        },
        renditions: true,
      },
    });

    if (!video) throw new NotFoundException('Video not found');

    // Check RBAC & Permissions
    await this.verifyDownloadPermission(userId, video);

    // Resolution selection (default to 720p or fallback to closest available)
    const targetRes = dto.resolution ?? VideoResolution.R_720P;
    const rendition =
      video.renditions.find((r) => r.resolution === targetRes) ||
      video.renditions.sort((a, b) => b.height - a.height)[0];

    const appUrl =
      this.configService.get<string>('APP_URL') ?? 'http://localhost:3000';

    // Generate signed download URL token
    const token = crypto.randomBytes(32).toString('hex');
    const expiresAt = new Date(Date.now() + 60 * 60 * 1000); // 1 hour validity

    const downloadUrl = `${appUrl}/api/downloads/file/${token}?res=${targetRes}`;

    // Create Download Audit Record
    const record = await this.repo.createRecord({
      userId,
      videoId: video.id,
      resolution: targetRes,
      signedUrl: downloadUrl,
      expiresAt,
      ipAddress,
      userAgent,
      fileSize: rendition ? rendition.fileSize : BigInt(0),
    });

    // Audit log entry
    await this.prisma.auditLog.create({
      data: {
        userId,
        action: 'VIDEO_DOWNLOAD_REQUESTED',
        resource: `Video:${video.id}`,
        details: { resolution: targetRes, recordId: record.id },
        ipAddress,
      },
    });

    // Increment video download count
    await this.prisma.video.update({
      where: { id: video.id },
      data: { downloadsCount: { increment: 1 } },
    });

    const safeTitle = video.title.replace(/[^a-zA-Z0-9_-]/g, '_');
    const filename = `${safeTitle}_${targetRes.toLowerCase()}.mp4`;

    return {
      downloadId: record.id,
      downloadUrl,
      expiresAt,
      resolution: targetRes,
      filename,
    };
  }

  /**
   * Authorize generic file download (Image, Audio, Document)
   */
  async authorizeFileDownload(
    userId: string,
    dto: RequestFileDownloadDto,
    ipAddress?: string,
    userAgent?: string,
  ) {
    const file = await this.prisma.file.findUnique({
      where: { id: dto.fileId, deletedAt: null },
      include: { group: { select: { id: true, status: true } } },
    });

    if (!file) throw new NotFoundException('File not found');

    // Group membership check for group files
    await this.verifyGroupFileAccess(userId, file.groupId);

    const appUrl =
      this.configService.get<string>('APP_URL') ?? 'http://localhost:3000';
    const token = crypto.randomBytes(32).toString('hex');
    const expiresAt = new Date(Date.now() + 60 * 60 * 1000);

    const downloadUrl = `${appUrl}/api/downloads/raw/${file.id}?token=${token}`;

    const record = await this.repo.createRecord({
      userId,
      fileId: file.id,
      signedUrl: downloadUrl,
      expiresAt,
      ipAddress,
      userAgent,
      fileSize: file.size,
    });

    return {
      downloadId: record.id,
      downloadUrl,
      expiresAt,
      filename: file.originalName,
    };
  }

  /**
   * Serve file download stream with Content-Disposition header
   */
  async getDownloadStreamInfo(downloadRecordId: string, userId: string) {
    const record = await this.prisma.downloadRecord.findUnique({
      where: { id: downloadRecordId },
      include: { video: { include: { renditions: true } }, file: true },
    });

    if (!record) throw new NotFoundException('Download record not found');
    if (record.userId !== userId) {
      const user = await this.prisma.user.findUnique({
        where: { id: userId },
        include: { role: true },
      });
      if (
        user?.role.name !== AppRole.SUPER_ADMIN &&
        user?.role.name !== AppRole.ADMIN
      ) {
        throw new ForbiddenException('Download record does not belong to user');
      }
    }

    let filePath: string | null = null;
    let filename = 'download.mp4';
    let mimeType = 'video/mp4';

    if (record.videoId && record.video) {
      const targetRes = record.resolution ?? VideoResolution.R_720P;
      const rendition = record.video.renditions.find(
        (r) => r.resolution === targetRes,
      );
      const relativeKey = rendition
        ? rendition.storageKey
        : `videos/${record.videoId}/master.m3u8`;
      filePath = path.resolve(process.cwd(), 'uploads', relativeKey);
      filename = `${record.video.title.replace(/[^a-zA-Z0-9_-]/g, '_')}_${targetRes.toLowerCase()}.mp4`;
    } else if (record.fileId && record.file) {
      filePath = path.resolve(process.cwd(), 'uploads', record.file.storageKey);
      filename = record.file.originalName;
      mimeType = record.file.mimeType;
    }

    // Update status to COMPLETED
    await this.repo.updateRecordStatus(
      downloadRecordId,
      DownloadStatus.COMPLETED,
      record.fileSize || BigInt(0),
    );

    return { filePath, filename, mimeType };
  }

  async getUserHistory(userId: string, page = 1, limit = 20) {
    return this.repo.getUserHistory(userId, page, limit);
  }

  async getDownloadStats(userId?: string) {
    return this.repo.getDownloadStats(userId);
  }

  private async verifyDownloadPermission(userId: string, video: any) {
    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      include: { role: true },
    });

    // SUPER_ADMIN has unrestricted download access
    if (
      user?.role.name === AppRole.SUPER_ADMIN ||
      user?.role.name === AppRole.ADMIN
    ) {
      return true;
    }

    const permission =
      video.downloadPermission || video.videoChannel.downloadPermission;

    if (permission === DownloadPermission.NONE) {
      throw new ForbiddenException('Downloads are disabled for this video');
    }

    if (permission === DownloadPermission.PUBLIC) {
      return true;
    }

    // Check Group RBAC
    const groupId = video.videoChannel.groupId;
    const member = await this.prisma.groupMember.findUnique({
      where: { groupId_userId: { groupId, userId }, removedAt: null },
    });

    if (!member) {
      throw new ForbiddenException(
        'You must be a member of the group to download this video',
      );
    }

    if (permission === DownloadPermission.SUBSCRIBERS_ONLY) {
      const isSubbed = await this.prisma.videoSubscription.findUnique({
        where: {
          userId_videoChannelId: {
            userId,
            videoChannelId: video.videoChannelId,
          },
        },
      });
      if (!isSubbed) {
        throw new ForbiddenException(
          'You must be subscribed to this channel to download',
        );
      }
    }

    return true;
  }

  private async verifyGroupFileAccess(userId: string, groupId: string) {
    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      include: { role: true },
    });

    if (
      user?.role.name === AppRole.SUPER_ADMIN ||
      user?.role.name === AppRole.ADMIN
    ) {
      return true;
    }

    const member = await this.prisma.groupMember.findUnique({
      where: { groupId_userId: { groupId, userId }, removedAt: null },
    });

    if (!member) {
      throw new ForbiddenException(
        'Access denied. You are not a member of this group.',
      );
    }
  }
}

// src/modules/group-join-requests/group-join-requests.service.ts
import {
  BadRequestException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { GroupJoinRequestsRepository } from './group-join-requests.repository.js';
import { GroupsRepository } from '../groups/groups.repository.js';
import { NotificationsService } from '../notifications/notifications.service.js';
import { CreateJoinRequestDto } from './dto/create-join-request.dto.js';
import { JoinRequestResponseDto } from './dto/join-request-response.dto.js';

@Injectable()
export class GroupJoinRequestsService {
  constructor(
    private readonly joinRequestsRepository: GroupJoinRequestsRepository,
    private readonly groupsRepository: GroupsRepository,
    private readonly notificationsService: NotificationsService,
  ) {}

  // ── Request to join a private group ──────────────────────────────────────

  async requestToJoin(
    groupId: string,
    userId: string,
    dto: CreateJoinRequestDto,
  ): Promise<JoinRequestResponseDto> {
    const group = await this.groupsRepository.findById(groupId);
    if (!group) throw new NotFoundException('Group not found');

    if (group.status !== 'ACTIVE') {
      throw new BadRequestException('Group is not active');
    }

    if (group.visibility === 'PUBLIC') {
      throw new BadRequestException(
        'This is a public group — you can join directly without a request',
      );
    }

    // Check if already a member
    const existingMember = await this.groupsRepository.getMember(
      groupId,
      userId,
    );
    if (existingMember) {
      throw new BadRequestException('You are already a member of this group');
    }

    // Check for duplicate pending request
    const pending = await this.joinRequestsRepository.findPendingByGroupAndUser(
      groupId,
      userId,
    );
    if (pending) {
      throw new BadRequestException(
        'You already have a pending join request for this group',
      );
    }

    const request = await this.joinRequestsRepository.create(
      groupId,
      userId,
      dto.note,
    );

    // Notify group admins
    const groupAdmins = await this.getGroupAdmins(groupId);
    await Promise.all(
      groupAdmins.map((adminId) =>
        this.notificationsService.notifyGroupJoinRequest(
          adminId,
          request.user.username ?? 'A user',
          groupId,
        ),
      ),
    );

    return this.mapToDto(request);
  }

  // ── List pending requests for a group (group admin only) ──────────────────

  async getPendingRequests(
    groupId: string,
    requestingUserId: string,
  ): Promise<JoinRequestResponseDto[]> {
    const group = await this.groupsRepository.findById(groupId);
    if (!group) throw new NotFoundException('Group not found');

    const member = await this.groupsRepository.getMember(
      groupId,
      requestingUserId,
    );
    if (!member || !['GROUP_ADMIN', 'MODERATOR'].includes(member.role)) {
      throw new ForbiddenException('Only group admins can view join requests');
    }

    const requests =
      await this.joinRequestsRepository.findPendingByGroup(groupId);
    return requests.map((r) => this.mapToDto(r));
  }

  // ── Get my own join requests ───────────────────────────────────────────────

  async getMyRequests(userId: string): Promise<JoinRequestResponseDto[]> {
    const requests = await this.joinRequestsRepository.findByUser(userId);
    return requests.map((r) => this.mapToDto(r));
  }

  // ── Approve a join request ─────────────────────────────────────────────────

  async approveRequest(
    requestId: string,
    approverId: string,
  ): Promise<JoinRequestResponseDto> {
    const request = await this.joinRequestsRepository.findById(requestId);
    if (!request) throw new NotFoundException('Join request not found');
    if (request.status !== 'PENDING') {
      throw new BadRequestException('Request has already been processed');
    }

    // Verify approver is group admin
    const member = await this.groupsRepository.getMember(
      request.groupId,
      approverId,
    );
    if (!member || !['GROUP_ADMIN', 'MODERATOR'].includes(member.role)) {
      throw new ForbiddenException(
        'Only group admins can approve join requests',
      );
    }

    // Add user to the group
    await this.groupsRepository.addMember(request.groupId, request.userId);

    // Update request status
    const approved = await this.joinRequestsRepository.approve(requestId);

    // Notify the user
    const group = await this.groupsRepository.findById(request.groupId);
    await this.notificationsService.notifyGroupApprove(
      request.userId,
      group?.name ?? 'the group',
      request.groupId,
    );

    return this.mapToDto(approved);
  }

  // ── Reject a join request ──────────────────────────────────────────────────

  async rejectRequest(
    requestId: string,
    rejecterId: string,
  ): Promise<JoinRequestResponseDto> {
    const request = await this.joinRequestsRepository.findById(requestId);
    if (!request) throw new NotFoundException('Join request not found');
    if (request.status !== 'PENDING') {
      throw new BadRequestException('Request has already been processed');
    }

    const member = await this.groupsRepository.getMember(
      request.groupId,
      rejecterId,
    );
    if (!member || !['GROUP_ADMIN', 'MODERATOR'].includes(member.role)) {
      throw new ForbiddenException(
        'Only group admins can reject join requests',
      );
    }

    const rejected = await this.joinRequestsRepository.reject(requestId);
    return this.mapToDto(rejected);
  }

  // ── Helper: get group admin user IDs ─────────────────────────────────────

  private async getGroupAdmins(groupId: string): Promise<string[]> {
    const group = await this.groupsRepository.findById(groupId);
    if (!group) return [];
    // createdBy is always an admin
    return [group.createdById];
  }

  // ── Mapper ─────────────────────────────────────────────────────────────────

  private mapToDto(r: any): JoinRequestResponseDto {
    return {
      id: r.id,
      groupId: r.groupId,
      userId: r.userId,
      username: r.user?.username ?? '',
      displayName: r.user?.profile?.displayName ?? undefined,
      avatarUrl: r.user?.profile?.avatar?.url ?? undefined,
      status: r.status,
      note: r.note ?? undefined,
      createdAt: r.createdAt,
      respondedAt: r.respondedAt ?? undefined,
    };
  }
}

import {
  ConnectedSocket,
  MessageBody,
  OnGatewayConnection,
  OnGatewayDisconnect,
  OnGatewayInit,
  SubscribeMessage,
  WebSocketGateway,
  WebSocketServer,
} from '@nestjs/websockets';
import { Logger, UsePipes, ValidationPipe } from '@nestjs/common';
import { Server, Socket } from 'socket.io';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import { StreamChatService } from '../stream-chat/stream-chat.service.js';
import { StreamAnalyticsService } from '../stream-analytics/stream-analytics.service.js';
import { StreamChatRepository } from '../stream-chat/stream-chat.repository.js';
import { PrismaService } from '../../prisma/prisma.service.js';
import { StreamChatMessageType } from '@prisma/client';

export const LIVE_EVENTS = {
  // Client → Server
  JOIN_STREAM: 'stream:join',
  LEAVE_STREAM: 'stream:leave',
  SEND_CHAT: 'chat:send',
  REACT_CHAT: 'chat:react',
  DELETE_CHAT: 'chat:delete',
  PIN_CHAT: 'chat:pin',
  POLL_VOTE: 'poll:vote',
  SEND_REACTION: 'reaction:send',
  STREAM_REPORT: 'stream:report',
  QUALITY_REPORT: 'quality:report',

  // Server → Client
  STREAM_STARTED: 'stream:started',
  STREAM_ENDED: 'stream:ended',
  STREAM_UPDATED: 'stream:updated',
  STREAM_ERROR: 'stream:error',
  CHAT_MESSAGE: 'chat:message',
  CHAT_DELETED: 'chat:deleted',
  CHAT_PINNED: 'chat:pinned',
  CHAT_REACTION: 'chat:reaction',
  VIEWER_COUNT: 'viewer:count',
  POLL_CREATED: 'poll:created',
  POLL_UPDATED: 'poll:updated',
  POLL_ENDED: 'poll:ended',
  REACTION_BROADCAST: 'reaction:broadcast',
  MOD_MUTED: 'mod:muted',
  MOD_BANNED: 'mod:banned',
  QUALITY_RECOMMEND: 'quality:recommend',
  ERROR: 'error',
} as const;

interface ViewerSession {
  userId: string;
  streamId: string;
  viewerId: string;
  joinedAt: number;
}

interface RateLimit {
  count: number;
  windowStart: number;
}

const CHAT_RATE_LIMIT = { max: 10, windowMs: 10_000 }; // 10 messages per 10 seconds
const REACTION_RATE_LIMIT = { max: 20, windowMs: 5_000 }; // 20 reactions per 5 seconds

@WebSocketGateway({
  cors: {
    origin: process.env.CORS_ORIGIN || '*',
    credentials: true,
  },
  namespace: '/live',
})
export class LiveGateway
  implements OnGatewayInit, OnGatewayConnection, OnGatewayDisconnect
{
  @WebSocketServer() declare server: Server;
  private readonly logger = new Logger(LiveGateway.name);

  // Map of viewer session records: socketId → session
  private readonly viewerSessions = new Map<string, ViewerSession>();
  // Rate limiting: userId:type → RateLimit
  private readonly rateLimits = new Map<string, RateLimit>();

  constructor(
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
    private readonly streamChatService: StreamChatService,
    private readonly streamAnalyticsService: StreamAnalyticsService,
    private readonly streamChatRepo: StreamChatRepository,
    private readonly prisma: PrismaService,
  ) {}

  afterInit(_server: Server) {
    this.logger.log('📡 LiveGateway initialized on /live namespace');
  }

  handleConnection(client: Socket) {
    try {
      const userId = this.authenticateSocket(client);
      client.data.userId = userId ?? null;
      this.logger.debug(
        `Client connected to /live: ${client.id} (User: ${userId ?? 'guest'})`,
      );
    } catch {
      client.data.userId = null;
      this.logger.debug(`Unauthenticated client connected: ${client.id}`);
    }
  }

  async handleDisconnect(client: Socket) {
    this.logger.debug(`Client disconnected: ${client.id}`);
    const session = this.viewerSessions.get(client.id);

    if (session) {
      const durationSec = Math.floor((Date.now() - session.joinedAt) / 1000);
      try {
        await this.streamAnalyticsService.trackViewerLeave(
          session.viewerId,
          durationSec,
        );
        const count = await this.getRoomViewerCount(session.streamId);
        this.server
          .to(`stream:${session.streamId}`)
          .emit(LIVE_EVENTS.VIEWER_COUNT, {
            streamId: session.streamId,
            count,
          });
      } catch (e) {
        this.logger.error('Error tracking viewer leave on disconnect', e);
      }
      this.viewerSessions.delete(client.id);
    }

    // Clean up rate limits
    this.cleanupRateLimits(client.data.userId as string | null);
  }

  // ─── Auth ────────────────────────────────────────────────────────────────

  private authenticateSocket(client: Socket): string | null {
    const token = this.extractToken(client);
    if (!token) return null;
    try {
      const payload = this.jwtService.verify(token, {
        secret: this.configService.get<string>('JWT_SECRET'),
      });
      return payload.sub as string;
    } catch {
      return null;
    }
  }

  private extractToken(client: Socket): string | null {
    const authHeader = client.handshake.headers.authorization;
    if (authHeader?.startsWith('Bearer ')) return authHeader.substring(7);
    const queryToken = client.handshake.query.token;
    if (typeof queryToken === 'string') return queryToken;
    return null;
  }

  // ─── Rate Limiting ────────────────────────────────────────────────────────

  private checkRateLimit(userId: string, type: 'chat' | 'reaction'): boolean {
    const key = `${userId}:${type}`;
    const limits = type === 'chat' ? CHAT_RATE_LIMIT : REACTION_RATE_LIMIT;
    const now = Date.now();

    const current = this.rateLimits.get(key);
    if (!current || now - current.windowStart > limits.windowMs) {
      this.rateLimits.set(key, { count: 1, windowStart: now });
      return true;
    }
    if (current.count >= limits.max) return false;
    current.count++;
    return true;
  }

  private cleanupRateLimits(userId: string | null) {
    if (!userId) return;
    this.rateLimits.delete(`${userId}:chat`);
    this.rateLimits.delete(`${userId}:reaction`);
  }

  // ─── Helpers ─────────────────────────────────────────────────────────────

  private async getRoomViewerCount(streamId: string): Promise<number> {
    const sockets = await this.server.in(`stream:${streamId}`).fetchSockets();
    return sockets.length;
  }

  /** Broadcast stream started event to all users */
  broadcastStreamStarted(streamId: string, stream: object) {
    this.server
      .to(`stream:${streamId}`)
      .emit(LIVE_EVENTS.STREAM_STARTED, stream);
  }

  /** Broadcast stream ended event to all users */
  broadcastStreamEnded(streamId: string, vodUrl?: string, duration?: number) {
    this.server.to(`stream:${streamId}`).emit(LIVE_EVENTS.STREAM_ENDED, {
      streamId,
      vodUrl,
      duration,
    });
  }

  /** Broadcast stream updated metadata */
  broadcastStreamUpdated(streamId: string, stream: object) {
    this.server
      .to(`stream:${streamId}`)
      .emit(LIVE_EVENTS.STREAM_UPDATED, stream);
  }

  /** Send moderation event to specific user */
  sendModerationEvent(streamId: string, event: string, data: object) {
    this.server.to(`stream:${streamId}`).emit(event, data);
  }

  // ─── Client → Server Events ──────────────────────────────────────────────

  @SubscribeMessage(LIVE_EVENTS.JOIN_STREAM)
  async handleJoinStream(
    @ConnectedSocket() client: Socket,
    @MessageBody('streamId') streamId: string,
  ) {
    if (!streamId) return;

    await client.join(`stream:${streamId}`);

    if (client.data.userId) {
      try {
        const viewer = await this.streamAnalyticsService.trackViewerJoin(
          streamId,
          client.data.userId as string,
        );
        this.viewerSessions.set(client.id, {
          userId: client.data.userId as string,
          streamId,
          viewerId: viewer.id,
          joinedAt: Date.now(),
        });
      } catch {
        this.logger.warn(
          `Failed to track viewer join for ${client.data.userId as string}`,
        );
      }
    }

    const count = await this.getRoomViewerCount(streamId);
    if (client.data.userId) {
      this.streamAnalyticsService
        .updateCurrentViewers(streamId, count, count)
        .catch(() => null);
    }

    this.server
      .to(`stream:${streamId}`)
      .emit(LIVE_EVENTS.VIEWER_COUNT, { streamId, count });
  }

  @SubscribeMessage(LIVE_EVENTS.LEAVE_STREAM)
  async handleLeaveStream(
    @ConnectedSocket() client: Socket,
    @MessageBody('streamId') streamId: string,
  ) {
    if (!streamId) return;

    await client.leave(`stream:${streamId}`);

    const session = this.viewerSessions.get(client.id);
    if (session && session.streamId === streamId) {
      const durationSec = Math.floor((Date.now() - session.joinedAt) / 1000);
      try {
        await this.streamAnalyticsService.trackViewerLeave(
          session.viewerId,
          durationSec,
        );
      } catch {
        // Non-critical
      }
      this.viewerSessions.delete(client.id);
    }

    const count = await this.getRoomViewerCount(streamId);
    this.server
      .to(`stream:${streamId}`)
      .emit(LIVE_EVENTS.VIEWER_COUNT, { streamId, count });
  }

  @UsePipes(new ValidationPipe({ transform: true }))
  @SubscribeMessage(LIVE_EVENTS.SEND_CHAT)
  async handleSendChat(
    @ConnectedSocket() client: Socket,
    @MessageBody()
    payload: {
      streamId: string;
      content: string;
      type?: StreamChatMessageType;
    },
  ) {
    const userId = client.data.userId as string | null;
    if (!userId) {
      client.emit(LIVE_EVENTS.ERROR, {
        message: 'Authentication required to send messages',
      });
      return;
    }

    if (!this.checkRateLimit(userId, 'chat')) {
      client.emit(LIVE_EVENTS.ERROR, {
        message: 'Slow down! You are sending messages too fast.',
      });
      return;
    }

    try {
      const chatRoom = await this.streamChatRepo.ensureChatRoomExists(
        payload.streamId,
      );
      const message = await this.streamChatRepo.saveMessage({
        chatRoomId: chatRoom.id,
        senderId: userId,
        content: payload.content,
        type: payload.type ?? StreamChatMessageType.TEXT,
      });

      this.server
        .to(`stream:${payload.streamId}`)
        .emit(LIVE_EVENTS.CHAT_MESSAGE, message);
      this.streamAnalyticsService
        .trackEngagement(payload.streamId, 'chat')
        .catch(() => null);
    } catch {
      client.emit(LIVE_EVENTS.ERROR, { message: 'Failed to send message' });
    }
  }

  @SubscribeMessage(LIVE_EVENTS.REACT_CHAT)
  async handleChatReaction(
    @ConnectedSocket() client: Socket,
    @MessageBody()
    payload: { streamId: string; messageId: string; emoji: string },
  ) {
    const userId = client.data.userId as string | null;
    if (!userId) {
      client.emit(LIVE_EVENTS.ERROR, { message: 'Authentication required' });
      return;
    }

    try {
      const reaction = await this.prisma.streamChatReaction.upsert({
        where: {
          messageId_userId_emoji: {
            messageId: payload.messageId,
            userId,
            emoji: payload.emoji,
          },
        },
        create: { messageId: payload.messageId, userId, emoji: payload.emoji },
        update: {},
      });

      // Count reactions for this emoji on this message
      const count = await this.prisma.streamChatReaction.count({
        where: { messageId: payload.messageId, emoji: payload.emoji },
      });

      this.server
        .to(`stream:${payload.streamId}`)
        .emit(LIVE_EVENTS.CHAT_REACTION, {
          messageId: payload.messageId,
          emoji: payload.emoji,
          count,
          reactionId: reaction.id,
        });
    } catch {
      client.emit(LIVE_EVENTS.ERROR, { message: 'Failed to add reaction' });
    }
  }

  @SubscribeMessage(LIVE_EVENTS.DELETE_CHAT)
  async handleDeleteChat(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: { streamId: string; messageId: string },
  ) {
    const userId = client.data.userId as string | null;
    if (!userId) {
      client.emit(LIVE_EVENTS.ERROR, { message: 'Authentication required' });
      return;
    }

    try {
      await this.streamChatService.deleteMessage(
        userId,
        payload.streamId,
        payload.messageId,
      );
      this.server
        .to(`stream:${payload.streamId}`)
        .emit(LIVE_EVENTS.CHAT_DELETED, {
          messageId: payload.messageId,
        });
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : 'Failed to delete message';
      client.emit(LIVE_EVENTS.ERROR, { message: msg });
    }
  }

  @SubscribeMessage(LIVE_EVENTS.PIN_CHAT)
  async handlePinChat(
    @ConnectedSocket() client: Socket,
    @MessageBody()
    payload: { streamId: string; messageId: string; pin: boolean },
  ) {
    const userId = client.data.userId as string | null;
    if (!userId) {
      client.emit(LIVE_EVENTS.ERROR, { message: 'Authentication required' });
      return;
    }

    try {
      const message = await this.streamChatService.pinMessage(
        userId,
        payload.streamId,
        payload.messageId,
        payload.pin !== false,
      );
      this.server
        .to(`stream:${payload.streamId}`)
        .emit(LIVE_EVENTS.CHAT_PINNED, { message });
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : 'Failed to pin message';
      client.emit(LIVE_EVENTS.ERROR, { message: msg });
    }
  }

  @SubscribeMessage(LIVE_EVENTS.POLL_VOTE)
  async handlePollVote(
    @ConnectedSocket() client: Socket,
    @MessageBody()
    payload: { streamId: string; pollId: string; optionId: string },
  ) {
    const userId = client.data.userId as string | null;
    if (!userId) {
      client.emit(LIVE_EVENTS.ERROR, {
        message: 'Authentication required to vote',
      });
      return;
    }

    try {
      // Check if user has already voted on this poll
      const existing = await this.prisma.streamPollVote.findUnique({
        where: { pollId_userId: { pollId: payload.pollId, userId } },
      });
      if (existing) {
        client.emit(LIVE_EVENTS.ERROR, {
          message: 'You have already voted on this poll',
        });
        return;
      }

      // Cast vote
      await this.prisma.$transaction([
        this.prisma.streamPollVote.create({
          data: { pollId: payload.pollId, optionId: payload.optionId, userId },
        }),
        this.prisma.streamPollOption.update({
          where: { id: payload.optionId },
          data: { voteCount: { increment: 1 } },
        }),
      ]);

      // Fetch updated poll for broadcast
      const poll = await this.prisma.streamPoll.findUnique({
        where: { id: payload.pollId },
        include: { options: true },
      });

      this.server
        .to(`stream:${payload.streamId}`)
        .emit(LIVE_EVENTS.POLL_UPDATED, { poll });
    } catch {
      client.emit(LIVE_EVENTS.ERROR, { message: 'Failed to record vote' });
    }
  }

  @SubscribeMessage(LIVE_EVENTS.SEND_REACTION)
  async handleSendReaction(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: { streamId: string; emoji: string },
  ) {
    const userId = client.data.userId as string | null;
    if (!userId) return; // Silently ignore unauthenticated reactions

    if (!this.checkRateLimit(userId, 'reaction')) return; // Rate limited - silent

    try {
      await this.prisma.streamReaction.create({
        data: { liveStreamId: payload.streamId, userId, emoji: payload.emoji },
      });

      // Count recent reactions for this emoji (last 5 seconds)
      const cutoff = new Date(Date.now() - 5000);
      const count = await this.prisma.streamReaction.count({
        where: {
          liveStreamId: payload.streamId,
          emoji: payload.emoji,
          createdAt: { gte: cutoff },
        },
      });

      this.server
        .to(`stream:${payload.streamId}`)
        .emit(LIVE_EVENTS.REACTION_BROADCAST, {
          emoji: payload.emoji,
          count,
        });

      this.streamAnalyticsService
        .trackEngagement(payload.streamId, 'reaction')
        .catch(() => null);
    } catch {
      // Non-critical — reactions can fail silently
    }
  }

  @SubscribeMessage(LIVE_EVENTS.QUALITY_REPORT)
  handleQualityReport(
    @ConnectedSocket() client: Socket,
    @MessageBody()
    payload: { streamId: string; quality: string; bandwidth: number },
  ) {
    // ABR quality feedback loop — currently logged for analytics
    // Future: aggregate and push quality:recommend to viewer
    if (payload.bandwidth < 500) {
      // Low bandwidth — recommend lower quality
      client.emit(LIVE_EVENTS.QUALITY_RECOMMEND, { quality: '240p' });
    } else if (payload.bandwidth > 4000) {
      client.emit(LIVE_EVENTS.QUALITY_RECOMMEND, { quality: '1080p' });
    }
  }
}

// src/modules/messages/messages.service.ts
import {
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { MessagesRepository } from './messages.repository.js';
import { ConversationsRepository } from '../conversations/conversations.repository.js';
import { SendMessageDto } from './dto/send-message.dto.js';
import { EditMessageDto } from './dto/edit-message.dto.js';
import { AddReactionDto } from './dto/add-reaction.dto.js';
import {
  MessageResponseDto,
  PaginatedMessagesDto,
} from './dto/message-response.dto.js';

@Injectable()
export class MessagesService {
  constructor(
    private readonly messagesRepository: MessagesRepository,
    private readonly conversationsRepository: ConversationsRepository,
  ) {}

  // ── Send a message to a conversation (DM or Channel) ──────────────────────

  async sendMessage(
    conversationId: string,
    senderId: string,
    dto: SendMessageDto,
  ): Promise<MessageResponseDto> {
    const conversation =
      await this.conversationsRepository.findById(conversationId);
    if (!conversation) {
      throw new NotFoundException('Conversation not found');
    }

    const isMember = conversation.members.some(
      (m: any) => m.userId === senderId,
    );
    if (!isMember) {
      throw new ForbiddenException('You are not a member of this conversation');
    }

    const message = await this.messagesRepository.create(
      conversationId,
      senderId,
      dto,
      conversation.channelId ?? undefined,
    );

    // Update conversation last message & unread counts
    await this.messagesRepository.updateConversationLastMessage(
      conversationId,
      message.id,
    );
    await this.messagesRepository.incrementUnreadCountForOthers(
      conversationId,
      senderId,
    );

    return this.mapToDto(message);
  }

  // ── Get paginated message history ─────────────────────────────────────────

  async getMessages(
    conversationId: string,
    userId: string,
    cursor?: string,
    limit = 50,
  ): Promise<PaginatedMessagesDto> {
    const conversation =
      await this.conversationsRepository.findById(conversationId);
    if (!conversation) {
      throw new NotFoundException('Conversation not found');
    }

    const isMember = conversation.members.some((m: any) => m.userId === userId);
    if (!isMember) {
      throw new ForbiddenException('You are not a member of this conversation');
    }

    const result = await this.messagesRepository.findByConversation(
      conversationId,
      cursor,
      limit,
    );

    // Mark all messages as read
    await this.messagesRepository.resetUnreadCount(conversationId, userId);

    return {
      data: result.data.map((m) => this.mapToDto(m)),
      nextCursor: result.nextCursor,
      hasMore: result.hasMore,
    };
  }

  // ── Edit message (owner only) ──────────────────────────────────────────────

  async editMessage(
    messageId: string,
    userId: string,
    dto: EditMessageDto,
  ): Promise<MessageResponseDto> {
    const message = await this.messagesRepository.findById(messageId);
    if (!message) {
      throw new NotFoundException('Message not found');
    }

    if (message.senderId !== userId) {
      throw new ForbiddenException('You can only edit your own messages');
    }

    if (message.deletedForEveryoneAt) {
      throw new ForbiddenException('Cannot edit a deleted message');
    }

    const updated = await this.messagesRepository.update(
      messageId,
      dto.content,
    );
    return this.mapToDto(updated);
  }

  // ── Delete for everyone (owner or group admin) ─────────────────────────────

  async deleteMessage(
    messageId: string,
    userId: string,
    isAdminOrModerator = false,
  ): Promise<{ success: boolean }> {
    const message = await this.messagesRepository.findById(messageId);
    if (!message) {
      throw new NotFoundException('Message not found');
    }

    if (message.senderId !== userId && !isAdminOrModerator) {
      throw new ForbiddenException(
        'You can only delete your own messages, or must be an admin/moderator',
      );
    }

    await this.messagesRepository.deleteForEveryone(messageId);
    return { success: true };
  }

  // ── React to message ───────────────────────────────────────────────────────

  async addReaction(
    messageId: string,
    userId: string,
    dto: AddReactionDto,
  ): Promise<{ success: boolean }> {
    const message = await this.messagesRepository.findById(messageId);
    if (!message) {
      throw new NotFoundException('Message not found');
    }

    await this.messagesRepository.addReaction(messageId, userId, dto.emoji);
    return { success: true };
  }

  async removeReaction(
    messageId: string,
    userId: string,
    emoji: string,
  ): Promise<{ success: boolean }> {
    await this.messagesRepository.removeReaction(messageId, userId, emoji);
    return { success: true };
  }

  // ── Mark as read ───────────────────────────────────────────────────────────

  async markAsRead(
    messageId: string,
    userId: string,
  ): Promise<{ success: boolean }> {
    const message = await this.messagesRepository.findById(messageId);
    if (!message) {
      throw new NotFoundException('Message not found');
    }

    await this.messagesRepository.markAsRead(messageId, userId);
    return { success: true };
  }

  // ── Pin/Unpin ──────────────────────────────────────────────────────────────

  async pinMessage(
    conversationId: string,
    messageId: string,
    userId: string,
  ): Promise<{ success: boolean }> {
    const message = await this.messagesRepository.findById(messageId);
    if (!message) {
      throw new NotFoundException('Message not found');
    }

    await this.messagesRepository.pinMessage(conversationId, messageId, userId);
    return { success: true };
  }

  async unpinMessage(
    conversationId: string,
    messageId: string,
  ): Promise<{ success: boolean }> {
    await this.messagesRepository.unpinMessage(conversationId, messageId);
    return { success: true };
  }

  async getPinnedMessages(
    conversationId: string,
  ): Promise<MessageResponseDto[]> {
    const pinned =
      await this.messagesRepository.getPinnedMessages(conversationId);
    return pinned.map((p: any) => this.mapToDto(p.message));
  }

  // ── Star/Unstar ────────────────────────────────────────────────────────────

  async starMessage(
    userId: string,
    messageId: string,
  ): Promise<{ success: boolean }> {
    await this.messagesRepository.starMessage(userId, messageId);
    return { success: true };
  }

  async unstarMessage(
    userId: string,
    messageId: string,
  ): Promise<{ success: boolean }> {
    await this.messagesRepository.unstarMessage(userId, messageId);
    return { success: true };
  }

  async getStarredMessages(userId: string): Promise<MessageResponseDto[]> {
    const starred = await this.messagesRepository.getStarredMessages(userId);
    return starred.map((s: any) => this.mapToDto(s.message));
  }

  // ── Mapper ─────────────────────────────────────────────────────────────────

  private mapToDto(message: any): MessageResponseDto {
    // Group reactions by emoji
    const reactionsMap: Record<string, { count: number; userIds: string[] }> =
      {};
    for (const r of message.reactions ?? []) {
      if (!reactionsMap[r.emoji]) {
        reactionsMap[r.emoji] = { count: 0, userIds: [] };
      }
      reactionsMap[r.emoji].count++;
      reactionsMap[r.emoji].userIds.push(r.userId as string);
    }

    return {
      id: message.id,
      conversationId: message.conversationId,
      channelId: message.channelId ?? undefined,
      sender: {
        id: message.sender.id,
        username: message.sender.username,
        displayName: message.sender.profile?.displayName ?? undefined,
        avatarUrl: message.sender.profile?.avatar?.url ?? undefined,
      },
      content: message.content ?? undefined,
      type: message.type,
      replyToId: message.replyToId ?? undefined,
      replyTo: message.replyTo
        ? {
            id: message.replyTo.id,
            content: message.replyTo.content,
            sender: {
              id: message.replyTo.sender.id,
              username: message.replyTo.sender.username,
              displayName:
                message.replyTo.sender.profile?.displayName ?? undefined,
            },
          }
        : undefined,
      isEdited: message.isEdited,
      isPinned: message.isPinned,
      attachments: (message.attachments ?? []).map((a: any) => ({
        fileId: a.file.id,
        url: a.file.url,
        fileType: a.file.fileType,
        mimeType: a.file.mimeType,
        originalName: a.file.originalName,
      })),
      reactions: Object.entries(reactionsMap).map(([emoji, data]) => ({
        emoji,
        count: data.count,
        userIds: data.userIds,
      })),
      readBy: (message.reads ?? []).map((r: any) => r.userId),
      createdAt: message.createdAt,
      updatedAt: message.updatedAt,
    };
  }
}

// src/modules/messaging-gateway/messaging.gateway.ts
import {
  ConnectedSocket,
  MessageBody,
  OnGatewayConnection,
  OnGatewayDisconnect,
  OnGatewayInit,
  SubscribeMessage,
  WebSocketGateway,
  WebSocketServer,
} from '@nestjs/websockets';
import { Logger } from '@nestjs/common';
import { Server, Socket } from 'socket.io';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import { MessagesService } from '../messages/messages.service.js';
import { ConversationsRepository } from '../conversations/conversations.repository.js';
import { PresenceService } from '../presence/presence.service.js';
import { SendMessageDto } from '../messages/dto/send-message.dto.js';
import { PresenceStatus } from '@prisma/client';

// ── WS Event Names ────────────────────────────────────────────────────────────
export const WS_EVENTS = {
  // Client → Server
  JOIN_CONVERSATION: 'conversation:join',
  LEAVE_CONVERSATION: 'conversation:leave',
  SEND_MESSAGE: 'message:send',
  TYPING_START: 'typing:start',
  TYPING_STOP: 'typing:stop',
  ADD_REACTION: 'reaction:add',
  REMOVE_REACTION: 'reaction:remove',
  MARK_READ: 'message:read',
  PRESENCE_UPDATE: 'presence:update',

  // Server → Client
  MESSAGE_NEW: 'message:new',
  MESSAGE_UPDATED: 'message:updated',
  MESSAGE_DELETED: 'message:deleted',
  REACTION_NEW: 'reaction:new',
  REACTION_REMOVED: 'reaction:removed',
  TYPING_INDICATOR: 'typing:indicator',
  READ_RECEIPT: 'message:receipt',
  PRESENCE_CHANGED: 'presence:changed',
  ERROR: 'error',
} as const;

@WebSocketGateway({
  cors: {
    origin: '*',
    methods: ['GET', 'POST'],
    credentials: true,
  },
  namespace: '/chat',
})
export class MessagingGateway
  implements OnGatewayInit, OnGatewayConnection, OnGatewayDisconnect
{
  @WebSocketServer() declare server: Server;

  private readonly logger = new Logger(MessagingGateway.name);
  private readonly userSocketMap = new Map<string, Set<string>>(); // userId → socketIds
  private readonly socketUserMap = new Map<string, string>(); // socketId → userId

  constructor(
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
    private readonly messagesService: MessagesService,
    private readonly conversationsRepository: ConversationsRepository,
    private readonly presenceService: PresenceService,
  ) {}

  afterInit(_server: Server) {
    this.logger.log('🔌 MessagingGateway initialized');
  }

  // ── Connection / Disconnection ────────────────────────────────────────────

  async handleConnection(client: Socket) {
    try {
      const userId = this.authenticateSocket(client);
      if (!userId) {
        client.emit(WS_EVENTS.ERROR, { message: 'Unauthorized' });
        client.disconnect(true);
        return;
      }

      // Register socket
      if (!this.userSocketMap.has(userId)) {
        this.userSocketMap.set(userId, new Set());
      }
      this.userSocketMap.get(userId)!.add(client.id);
      this.socketUserMap.set(client.id, userId);

      // Store userId on socket for later use
      (client as any).userId = userId;

      this.logger.log(`Client connected: ${client.id} (user: ${userId})`);

      // Update DB presence
      await this.presenceService.setStatus(userId, PresenceStatus.ONLINE);

      // Notify others of online presence
      this.server.emit(WS_EVENTS.PRESENCE_CHANGED, {
        userId,
        status: PresenceStatus.ONLINE,
      });
    } catch {
      client.disconnect(true);
    }
  }

  async handleDisconnect(client: Socket) {
    const userId = this.socketUserMap.get(client.id);
    if (userId) {
      const sockets = this.userSocketMap.get(userId);
      sockets?.delete(client.id);
      if (!sockets?.size) {
        this.userSocketMap.delete(userId);

        // Update DB presence
        await this.presenceService.setOffline(userId).catch(() => {});

        this.server.emit(WS_EVENTS.PRESENCE_CHANGED, {
          userId,
          status: PresenceStatus.OFFLINE,
          lastSeenAt: new Date(),
        });
      }
      this.socketUserMap.delete(client.id);
    }
    this.logger.log(`Client disconnected: ${client.id}`);
  }

  // ── Join / Leave Conversation Room ────────────────────────────────────────

  @SubscribeMessage(WS_EVENTS.JOIN_CONVERSATION)
  async handleJoinConversation(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { conversationId: string },
  ) {
    const userId = (client as any).userId as string;
    const conversation = await this.conversationsRepository.findById(
      data.conversationId,
    );

    if (!conversation) {
      client.emit(WS_EVENTS.ERROR, { message: 'Conversation not found' });
      return;
    }

    const isMember = conversation.members.some((m: any) => m.userId === userId);
    if (!isMember) {
      client.emit(WS_EVENTS.ERROR, {
        message: 'Not a member of this conversation',
      });
      return;
    }

    await client.join(`conversation:${data.conversationId}`);
    this.logger.log(
      `User ${userId} joined conversation ${data.conversationId}`,
    );
  }

  @SubscribeMessage(WS_EVENTS.LEAVE_CONVERSATION)
  handleLeaveConversation(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { conversationId: string },
  ) {
    client.leave(`conversation:${data.conversationId}`);
  }

  // ── Send Message ──────────────────────────────────────────────────────────

  @SubscribeMessage(WS_EVENTS.SEND_MESSAGE)
  async handleSendMessage(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { conversationId: string } & SendMessageDto,
  ) {
    const userId = (client as any).userId as string;

    try {
      const { conversationId, ...dto } = data;
      const message = await this.messagesService.sendMessage(
        conversationId,
        userId,
        dto,
      );

      // Broadcast to all members of the conversation room
      this.server
        .to(`conversation:${conversationId}`)
        .emit(WS_EVENTS.MESSAGE_NEW, message);

      return { success: true, message };
    } catch (err: any) {
      client.emit(WS_EVENTS.ERROR, { message: err.message });
    }
  }

  // ── Typing Indicators ─────────────────────────────────────────────────────

  @SubscribeMessage(WS_EVENTS.TYPING_START)
  handleTypingStart(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { conversationId: string },
  ) {
    const userId = (client as any).userId as string;
    client
      .to(`conversation:${data.conversationId}`)
      .emit(WS_EVENTS.TYPING_INDICATOR, {
        userId,
        conversationId: data.conversationId,
        isTyping: true,
      });
  }

  @SubscribeMessage(WS_EVENTS.TYPING_STOP)
  handleTypingStop(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { conversationId: string },
  ) {
    const userId = (client as any).userId as string;
    client
      .to(`conversation:${data.conversationId}`)
      .emit(WS_EVENTS.TYPING_INDICATOR, {
        userId,
        conversationId: data.conversationId,
        isTyping: false,
      });
  }

  // ── Reactions ─────────────────────────────────────────────────────────────

  @SubscribeMessage(WS_EVENTS.ADD_REACTION)
  async handleAddReaction(
    @ConnectedSocket() client: Socket,
    @MessageBody()
    data: { messageId: string; conversationId: string; emoji: string },
  ) {
    const userId = (client as any).userId as string;
    try {
      await this.messagesService.addReaction(messageId(data), userId, {
        emoji: data.emoji,
      });
      this.server
        .to(`conversation:${data.conversationId}`)
        .emit(WS_EVENTS.REACTION_NEW, {
          messageId: data.messageId,
          userId,
          emoji: data.emoji,
        });
    } catch (err: any) {
      client.emit(WS_EVENTS.ERROR, { message: err.message });
    }
  }

  @SubscribeMessage(WS_EVENTS.REMOVE_REACTION)
  async handleRemoveReaction(
    @ConnectedSocket() client: Socket,
    @MessageBody()
    data: { messageId: string; conversationId: string; emoji: string },
  ) {
    const userId = (client as any).userId as string;
    try {
      await this.messagesService.removeReaction(
        data.messageId,
        userId,
        data.emoji,
      );
      this.server
        .to(`conversation:${data.conversationId}`)
        .emit(WS_EVENTS.REACTION_REMOVED, {
          messageId: data.messageId,
          userId,
          emoji: data.emoji,
        });
    } catch (err: any) {
      client.emit(WS_EVENTS.ERROR, { message: err.message });
    }
  }

  // ── Mark as Read ──────────────────────────────────────────────────────────

  @SubscribeMessage(WS_EVENTS.MARK_READ)
  async handleMarkRead(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { messageId: string; conversationId: string },
  ) {
    const userId = (client as any).userId as string;
    try {
      await this.messagesService.markAsRead(data.messageId, userId);
      this.server
        .to(`conversation:${data.conversationId}`)
        .emit(WS_EVENTS.READ_RECEIPT, {
          messageId: data.messageId,
          userId,
          readAt: new Date(),
        });
    } catch (err: any) {
      client.emit(WS_EVENTS.ERROR, { message: err.message });
    }
  }

  // ── Helpers ───────────────────────────────────────────────────────────────

  private authenticateSocket(client: Socket): string | null {
    try {
      const token =
        client.handshake.auth?.token ||
        client.handshake.headers.authorization?.replace('Bearer ', '');

      if (!token) return null;

      const payload = this.jwtService.verify(token, {
        secret: this.configService.get<string>('JWT_SECRET'),
      });

      return payload.sub as string;
    } catch {
      return null;
    }
  }

  /** Broadcast a message update to a conversation room (used by MessagesService internally) */
  emitMessageUpdated(conversationId: string, message: any) {
    this.server
      .to(`conversation:${conversationId}`)
      .emit(WS_EVENTS.MESSAGE_UPDATED, message);
  }

  emitMessageDeleted(conversationId: string, messageId: string) {
    this.server
      .to(`conversation:${conversationId}`)
      .emit(WS_EVENTS.MESSAGE_DELETED, { messageId });
  }

  /** Check if a user is currently online */
  isUserOnline(userId: string): boolean {
    return (this.userSocketMap.get(userId)?.size ?? 0) > 0;
  }
}

// helper to reduce a type error below
function messageId(data: { messageId: string }) {
  return data.messageId;
}

