// src/modules/notifications/notifications.gateway.ts
import {
  OnGatewayConnection,
  OnGatewayDisconnect,
  OnGatewayInit,
  WebSocketGateway,
  WebSocketServer,
} from '@nestjs/websockets';
import { Logger } from '@nestjs/common';
import { Server, Socket } from 'socket.io';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import { NotificationResponseDto } from './dto/notification-response.dto.js';

@WebSocketGateway({
  cors: {
    origin: '*',
    methods: ['GET', 'POST'],
    credentials: true,
  },
  namespace: '/notifications',
})
export class NotificationsGateway
  implements OnGatewayInit, OnGatewayConnection, OnGatewayDisconnect
{
  @WebSocketServer() declare server: Server;
  private readonly logger = new Logger(NotificationsGateway.name);

  constructor(
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
  ) {}

  afterInit(_server: Server) {
    this.logger.log('🔔 NotificationsGateway initialized');
  }

  handleConnection(client: Socket) {
    try {
      const token = this.extractToken(client);
      if (!token) {
        client.disconnect(true);
        return;
      }

      const payload = this.jwtService.verify(token, {
        secret: this.configService.get<string>('JWT_ACCESS_SECRET'),
      });
      const userId = payload.sub;

      // Join a personal room for this user to receive their own notifications
      void client.join(`user:${userId}`);
      this.logger.log(
        `Client ${client.id} joined notifications (user: ${userId})`,
      );
    } catch {
      client.disconnect(true);
    }
  }

  handleDisconnect(client: Socket) {
    this.logger.log(`Client disconnected from notifications: ${client.id}`);
  }

  private extractToken(client: Socket): string | undefined {
    const authHeader = client.handshake.headers.authorization;
    if (authHeader && authHeader.startsWith('Bearer ')) {
      return authHeader.substring(7);
    }
    const tokenQuery =
      client.handshake.auth?.token || client.handshake.query?.token;
    if (typeof tokenQuery === 'string') {
      return tokenQuery;
    }
    return undefined;
  }

  public emitNotification(
    userId: string,
    notification: NotificationResponseDto,
  ) {
    this.server.to(`user:${userId}`).emit('notification:new', notification);
  }
}

// src/modules/notifications/notifications.repository.ts
import { Injectable } from '@nestjs/common';
import { NotificationType } from '@prisma/client';
import { PrismaService } from '../../prisma/prisma.service.js';

@Injectable()
export class NotificationsRepository {
  constructor(private readonly prisma: PrismaService) {}

  async create(payload: {
    userId: string;
    type: NotificationType;
    title: string;
    body: string;
    data?: Record<string, any>;
  }) {
    return this.prisma.notification.create({ data: payload });
  }

  async findByUser(userId: string, onlyUnread = false) {
    return this.prisma.notification.findMany({
      where: { userId, ...(onlyUnread ? { isRead: false } : {}) },
      orderBy: { createdAt: 'desc' },
      take: 50,
    });
  }

  async markAsRead(id: string, userId: string) {
    return this.prisma.notification.updateMany({
      where: { id, userId },
      data: { isRead: true },
    });
  }

  async markAllAsRead(userId: string) {
    return this.prisma.notification.updateMany({
      where: { userId, isRead: false },
      data: { isRead: true },
    });
  }

  async delete(id: string, userId: string) {
    return this.prisma.notification.deleteMany({ where: { id, userId } });
  }

  async unreadCount(userId: string): Promise<number> {
    return this.prisma.notification.count({ where: { userId, isRead: false } });
  }
}

// src/modules/notifications/notifications.service.ts
import { Injectable, forwardRef, Inject } from '@nestjs/common';
import { NotificationType } from '@prisma/client';
import { NotificationsRepository } from './notifications.repository.js';
import { NotificationResponseDto } from './dto/notification-response.dto.js';
import { NotificationsGateway } from './notifications.gateway.js';

@Injectable()
export class NotificationsService {
  constructor(
    private readonly notificationsRepository: NotificationsRepository,
    @Inject(forwardRef(() => NotificationsGateway))
    private readonly notificationsGateway: NotificationsGateway,
  ) {}

  // ── Create (used internally by other services) ─────────────────────────────
  async create(payload: {
    userId: string;
    type: NotificationType;
    title: string;
    body: string;
    data?: Record<string, any>;
  }): Promise<NotificationResponseDto> {
    const notif = await this.notificationsRepository.create(payload);
    const dto = this.mapToDto(notif);

    // Push real-time notification
    this.notificationsGateway.emitNotification(payload.userId, dto);

    return dto;
  }

  // ── Factory helpers ────────────────────────────────────────────────────────

  async notifyMessage(
    recipientId: string,
    senderName: string,
    preview: string,
    conversationId: string,
  ) {
    return this.create({
      userId: recipientId,
      type: NotificationType.MESSAGE,
      title: `New message from ${senderName}`,
      body: preview,
      data: { conversationId },
    });
  }

  async notifyGroupInvite(
    recipientId: string,
    groupName: string,
    groupId: string,
  ) {
    return this.create({
      userId: recipientId,
      type: NotificationType.GROUP_INVITE,
      title: `You have been invited to ${groupName}`,
      body: 'Tap to view the invitation',
      data: { groupId },
    });
  }

  async notifyGroupJoinRequest(
    adminId: string,
    requesterName: string,
    groupId: string,
  ) {
    return this.create({
      userId: adminId,
      type: NotificationType.GROUP_JOIN_REQUEST,
      title: `${requesterName} wants to join your group`,
      body: 'Review the join request',
      data: { groupId },
    });
  }

  async notifyGroupApprove(userId: string, groupName: string, groupId: string) {
    return this.create({
      userId,
      type: NotificationType.GROUP_APPROVE,
      title: `Your request to join ${groupName} was approved`,
      body: 'You are now a member of the group',
      data: { groupId },
    });
  }

  async notifyMention(
    recipientId: string,
    senderName: string,
    context: string,
    conversationId: string,
  ) {
    return this.create({
      userId: recipientId,
      type: NotificationType.MENTION,
      title: `${senderName} mentioned you`,
      body: context,
      data: { conversationId },
    });
  }

  async notifyReaction(
    recipientId: string,
    senderName: string,
    emoji: string,
    messageId: string,
  ) {
    return this.create({
      userId: recipientId,
      type: NotificationType.REACTION,
      title: `${senderName} reacted ${emoji} to your message`,
      body: '',
      data: { messageId },
    });
  }

  // ── User-facing queries ────────────────────────────────────────────────────

  async getMyNotifications(userId: string): Promise<NotificationResponseDto[]> {
    const notifications = await this.notificationsRepository.findByUser(userId);
    return notifications.map((n) => this.mapToDto(n));
  }

  async getUnreadNotifications(
    userId: string,
  ): Promise<NotificationResponseDto[]> {
    const notifications = await this.notificationsRepository.findByUser(
      userId,
      true,
    );
    return notifications.map((n) => this.mapToDto(n));
  }

  async getUnreadCount(userId: string): Promise<{ count: number }> {
    const count = await this.notificationsRepository.unreadCount(userId);
    return { count };
  }

  async markAsRead(id: string, userId: string): Promise<{ success: boolean }> {
    await this.notificationsRepository.markAsRead(id, userId);
    return { success: true };
  }

  async markAllAsRead(userId: string): Promise<{ success: boolean }> {
    await this.notificationsRepository.markAllAsRead(userId);
    return { success: true };
  }

  async delete(id: string, userId: string): Promise<{ success: boolean }> {
    await this.notificationsRepository.delete(id, userId);
    return { success: true };
  }

  // ── Mapper ─────────────────────────────────────────────────────────────────
  private mapToDto(n: any): NotificationResponseDto {
    return {
      id: n.id,
      type: n.type,
      title: n.title,
      body: n.body,
      data: n.data ?? undefined,
      isRead: n.isRead,
      createdAt: n.createdAt,
    };
  }
}

// src/modules/posts/posts.service.ts
import {
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { PostsRepository } from './posts.repository.js';
import { CreatePostDto } from './dto/create-post.dto.js';
import { UpdatePostDto } from './dto/update-post.dto.js';
import { PostResponseDto } from './dto/post-response.dto.js';

@Injectable()
export class PostsService {
  constructor(private readonly postsRepository: PostsRepository) {}

  async createPost(
    authorId: string,
    dto: CreatePostDto,
  ): Promise<PostResponseDto> {
    const post = await this.postsRepository.createPost(authorId, dto);
    if (!post) {
      throw new NotFoundException('Failed to create post');
    }
    return this.mapToDto(post);
  }

  async getPostById(postId: string): Promise<PostResponseDto> {
    const post = await this.postsRepository.findById(postId);
    if (!post) {
      throw new NotFoundException('Post not found');
    }
    await this.postsRepository.incrementViews(postId);
    return this.mapToDto(post);
  }

  async updatePost(
    postId: string,
    userId: string,
    dto: UpdatePostDto,
  ): Promise<PostResponseDto> {
    const post = await this.postsRepository.findById(postId);
    if (!post) {
      throw new NotFoundException('Post not found');
    }

    if (post.authorId !== userId) {
      throw new ForbiddenException('You can only update your own posts');
    }

    await this.postsRepository.updatePost(postId, dto);
    const updated = await this.postsRepository.findById(postId);
    return this.mapToDto(updated!);
  }

  async deletePost(
    postId: string,
    userId: string,
  ): Promise<{ message: string }> {
    const post = await this.postsRepository.findById(postId);
    if (!post) {
      throw new NotFoundException('Post not found');
    }

    if (post.authorId !== userId) {
      throw new ForbiddenException('You can only delete your own posts');
    }

    await this.postsRepository.softDeletePost(postId);
    return { message: 'Post deleted successfully' };
  }

  async getFeed(
    page = 1,
    limit = 20,
    authorId?: string,
    groupId?: string,
    hashtag?: string,
  ) {
    const skip = (page - 1) * limit;
    const { items, total } = await this.postsRepository.findFeed({
      skip,
      take: limit,
      authorId,
      groupId,
      hashtag,
    });

    const data = items.map((post) => this.mapToDto(post));

    return {
      data,
      meta: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
        hasNext: page * limit < total,
        hasPrev: page > 1,
      },
    };
  }

  private mapToDto(post: any): PostResponseDto {
    return {
      id: post.id,
      type: post.type,
      visibility: post.visibility,
      content: post.content,
      hashtags: post.hashtags ?? [],
      likesCount: post.likesCount ?? 0,
      commentsCount: post.commentsCount ?? 0,
      viewsCount: post.viewsCount ?? 0,
      groupId: post.groupId,
      author: {
        id: post.author.id,
        username: post.author.username,
        displayName: post.author.profile?.displayName ?? post.author.username,
        avatarUrl: post.author.profile?.avatar?.url ?? null,
      },
      media: (post.media ?? []).map((m: any) => ({
        id: m.file.id,
        url: m.file.url,
        fileType: m.file.fileType,
        order: m.order,
      })),
      createdAt: post.createdAt,
      updatedAt: post.updatedAt,
    };
  }
}

