import { Controller, Get, Param, UseGuards } from '@nestjs/common';
import {
  ApiTags,
  ApiOperation,
  ApiBearerAuth,
  ApiParam,
} from '@nestjs/swagger';
import { StreamAnalyticsService } from './stream-analytics.service.js';
import { JwtAuthGuard } from '../../common/guards/jwt-auth.guard.js';
import { CurrentUser } from '../../common/decorators/current-user.decorator.js';

@ApiTags('Stream Analytics')
@Controller('streams/:streamId/analytics')
export class StreamAnalyticsController {
  constructor(
    private readonly streamAnalyticsService: StreamAnalyticsService,
  ) {}

  @Get()
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Get full analytics report (Moderator only)' })
  @ApiParam({ name: 'streamId', description: 'Live Stream ID' })
  async getAnalytics(
    @CurrentUser('sub') userId: string,
    @Param('streamId') streamId: string,
  ) {
    return this.streamAnalyticsService.getAnalytics(userId, streamId);
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service.js';
import { Prisma } from '@prisma/client';

@Injectable()
export class StreamAnalyticsRepository {
  constructor(private readonly prisma: PrismaService) {}

  async getAnalytics(liveStreamId: string): Promise<StreamAnalytics | null> {
    return this.prisma.streamAnalytics.findUnique({
      where: { liveStreamId },
    });
  }

  async ensureAnalyticsExists(liveStreamId: string): Promise<StreamAnalytics> {
    const analytics = await this.getAnalytics(liveStreamId);
    if (analytics) return analytics;

    return this.prisma.streamAnalytics.create({
      data: { liveStreamId },
    });
  }

  async updateViewerCount(
    liveStreamId: string,
    currentViewers: number,
    peakViewers: number,
  ) {
    // Update live stream stats
    await this.prisma.liveStream.update({
      where: { id: liveStreamId },
      data: {
        currentViewerCount: currentViewers,
        peakViewerCount: { set: Math.max(peakViewers, currentViewers) }, // Only increase peak
      },
    });

    // Update analytics peak
    await this.ensureAnalyticsExists(liveStreamId);
    await this.prisma.streamAnalytics.update({
      where: { liveStreamId },
      data: {
        peakConcurrentViewers: { set: Math.max(peakViewers, currentViewers) },
      },
    });
  }

  async recordViewerJoin(liveStreamId: string, userId: string) {
    return this.prisma.streamViewer.create({
      data: {
        liveStreamId,
        userId,
      },
    });
  }

  async recordViewerLeave(viewerId: string, watchDuration: number) {
    return this.prisma.streamViewer.update({
      where: { id: viewerId },
      data: {
        leftAt: new Date(),
        watchDuration,
      },
    });
  }

  async incrementEngagement(
    liveStreamId: string,
    field: 'totalChatMessages' | 'totalReactions' | 'totalLikes',
    amount = 1,
  ) {
    await this.ensureAnalyticsExists(liveStreamId);

    const liveStreamData =
      field === 'totalChatMessages'
        ? { totalChatMessages: { increment: amount } }
        : field === 'totalReactions'
          ? { totalReactions: { increment: amount } }
          : { likesCount: { increment: amount } };

    const analyticsData =
      field === 'totalChatMessages'
        ? { totalChatMessages: { increment: amount } }
        : field === 'totalReactions'
          ? { totalReactions: { increment: amount } }
          : { totalLikes: { increment: amount } };

    await this.prisma.$transaction([
      this.prisma.liveStream.update({
        where: { id: liveStreamId },
        data: liveStreamData,
      }),
      this.prisma.streamAnalytics.update({
        where: { liveStreamId },
        data: analyticsData,
      }),
    ]);
  }
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { StreamAnalyticsRepository } from './stream-analytics.repository.js';
import { LiveStreamingRepository } from '../live-streaming/live-streaming.repository.js';
import { AuthorizationService } from '../authorization/authorization.service.js';
import { GroupRole } from '../../common/constants/group-roles.js';

@Injectable()
export class StreamAnalyticsService {
  constructor(
    private readonly repository: StreamAnalyticsRepository,
    private readonly liveStreamingRepository: LiveStreamingRepository,
    private readonly authorizationService: AuthorizationService,
  ) {}

  async getAnalytics(userId: string, streamId: string) {
    const stream = await this.liveStreamingRepository.getStreamById(streamId);
    if (!stream) throw new NotFoundException('Stream not found');

    const hasPermission = await this.authorizationService.hasGroupRole(
      userId,
      stream.groupId,
      GroupRole.MODERATOR,
    );
    if (!hasPermission) throw new ForbiddenException('Not a moderator');

    const analytics = await this.repository.getAnalytics(streamId);
    if (!analytics) throw new NotFoundException('Analytics not available yet');

    return analytics;
  }

  // To be used internally by LiveGateway
  async trackViewerJoin(streamId: string, userId: string) {
    return this.repository.recordViewerJoin(streamId, userId);
  }

  async trackViewerLeave(viewerSessionId: string, durationSec: number) {
    return this.repository.recordViewerLeave(viewerSessionId, durationSec);
  }

  async updateCurrentViewers(streamId: string, current: number, peak: number) {
    return this.repository.updateViewerCount(streamId, current, peak);
  }

  async trackEngagement(streamId: string, type: 'chat' | 'reaction' | 'like') {
    const fieldMap = {
      chat: 'totalChatMessages',
      reaction: 'totalReactions',
      like: 'totalLikes',
    } as const;
    return this.repository.incrementEngagement(streamId, fieldMap[type]);
  }
}

