  ) {
    const stream = await this.liveStreamingRepository.getStreamById(streamId);
    if (!stream) throw new NotFoundException('Stream not found');

    if (stream.visibility !== 'PUBLIC') {
      if (!userId) throw new ForbiddenException('Authentication required');
      const hasMemberRole = await this.authorizationService.hasGroupRole(
        userId,
        stream.groupId,
        GroupRole.MEMBER,
      );
      if (!hasMemberRole)
        throw new ForbiddenException('You cannot access this stream chat');
    }

    const chatRoom = await this.repository.getChatRoomByStreamId(streamId);
    if (!chatRoom) return [];

    return this.repository.getMessages(chatRoom.id, limit, cursor);
  }

  async deleteMessage(userId: string, streamId: string, messageId: string) {
    const stream = await this.liveStreamingRepository.getStreamById(streamId);
    if (!stream) throw new NotFoundException('Stream not found');

    const hasPermission = await this.authorizationService.hasGroupRole(
      userId,
      stream.groupId,
      GroupRole.MODERATOR,
    );
    if (!hasPermission) throw new ForbiddenException('Not a moderator');

    const message = await this.repository.getMessageById(messageId);
    const chatRoom = await this.repository.getChatRoomByStreamId(streamId);
    if (!message || message.chatRoomId !== chatRoom?.id) {
      throw new NotFoundException('Message not found');
    }

    return this.repository.deleteMessage(messageId);
  }

  async pinMessage(
    userId: string,
    streamId: string,
    messageId: string,
    isPinned: boolean,
  ) {
    const stream = await this.liveStreamingRepository.getStreamById(streamId);
    if (!stream) throw new NotFoundException('Stream not found');

    const hasPermission = await this.authorizationService.hasGroupRole(
      userId,
      stream.groupId,
      GroupRole.MODERATOR,
    );
    if (!hasPermission) throw new ForbiddenException('Not a moderator');

    const message = await this.repository.getMessageById(messageId);
    const chatRoom = await this.repository.getChatRoomByStreamId(streamId);
    if (!message || message.chatRoomId !== chatRoom?.id) {
      throw new NotFoundException('Message not found');
    }

    return this.repository.pinMessage(messageId, isPinned);
  }
}

import { Processor, WorkerHost, OnWorkerEvent } from '@nestjs/bullmq';
import { Logger } from '@nestjs/common';
import { Job } from 'bullmq';
import { ProcessRecordingJobData } from './stream-processing.service.js';
import { PrismaService } from '../../prisma/prisma.service.js';
import { StreamRecordingStatus } from '@prisma/client';

export const STREAM_PROCESSING_QUEUE = 'stream-processing';

@Processor(STREAM_PROCESSING_QUEUE)
export class StreamProcessingProcessor extends WorkerHost {
  private readonly logger = new Logger(StreamProcessingProcessor.name);

  constructor(private readonly prisma: PrismaService) {
    super();
  }

  async process(job: Job<ProcessRecordingJobData>): Promise<void> {
    const {
      liveStreamId,
      recordingId,
      recordingPath: _recordingPath,
    } = job.data;

    this.logger.log(
      `Processing recording for stream ${liveStreamId} (Job: ${job.id})`,
    );

    // 1. Update status to PROCESSING
    await this.prisma.streamRecording.update({
      where: { id: recordingId },
      data: {
        status: StreamRecordingStatus.PROCESSING,
        processingJobId: job.id,
      },
    });

    try {
      // Here we would run FFmpeg to transcode the recording to HLS (ABR)
      // For this implementation plan, we simulate processing time
      await new Promise((resolve) => setTimeout(resolve, 5000));

      const mockHlsUrl = `/recordings/${liveStreamId}/master.m3u8`;

      // 2. Mark as READY
      await this.prisma.streamRecording.update({
        where: { id: recordingId },
        data: {
          status: StreamRecordingStatus.READY,
          hlsUrl: mockHlsUrl,
          duration: 3600, // Mock 1 hour
          completedAt: new Date(),
        },
      });

      this.logger.log(`Finished processing recording ${recordingId}`);
    } catch (error) {
      this.logger.error(`Failed to process recording ${recordingId}`, error);

      // 3. Mark as FAILED on error
      await this.prisma.streamRecording.update({
        where: { id: recordingId },
        data: { status: StreamRecordingStatus.FAILED },
      });
      throw error;
    }
  }

  @OnWorkerEvent('failed')
  onFailed(job: Job<ProcessRecordingJobData>, error: Error) {
    this.logger.error(`Job ${job.id} failed: ${error.message}`, error.stack);
  }
}

// src/modules/uploads/uploads.service.ts
import 'multer';
import {
  BadRequestException,
  Inject,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import crypto from 'crypto';
import path from 'path';
import { FileProvider, FileType } from '@prisma/client';
import { UploadsRepository } from './uploads.repository.js';
import { IStorageProvider } from './providers/storage.interface.js';
import { STORAGE_PROVIDER_TOKEN } from './providers/storage.factory.js';
import { FileResponseDto } from './dto/file-response.dto.js';
import { PrismaService } from '../../prisma/prisma.service.js';

@Injectable()
export class UploadsService {
  constructor(
    private readonly uploadsRepository: UploadsRepository,
    @Inject(STORAGE_PROVIDER_TOKEN)
    private readonly storageProvider: IStorageProvider & Record<string, any>,
    private readonly prisma: PrismaService,
  ) {}

  /**
   * Group-scoped file upload endpoint requirement:
   * Validates group status, user membership, MIME type, file size,
   * uploads to configured storage (Local or Cloudinary fallback),
   * and saves database record.
   */
  async uploadGroupFile(
    groupId: string,
    uploaderId: string,
    file: Express.Multer.File,
  ): Promise<FileResponseDto> {
    if (!file) {
      throw new BadRequestException('File is required');
    }

    // 1. Verify Group exists and is ACTIVE
    const group = await this.prisma.group.findUnique({
      where: { id: groupId, deletedAt: null },
      select: { id: true, status: true },
    });

    if (!group) {
      throw new NotFoundException('Group not found');
    }

    if (group.status !== 'ACTIVE') {
      throw new ForbiddenException(
        'This group is pending approval or inactive — uploads are disabled until approved by an Admin',
      );
    }

    // 2. Determine file category (IMAGE, VIDEO, AUDIO, DOCUMENT, etc.)
    const fileType = this.resolveFileType(file.mimetype);

    // 3. Compute SHA-256 checksum
    const checksum = crypto
      .createHash('sha256')
      .update(file.buffer)
      .digest('hex');

    // 4. Upload via storage provider
    const subfolder = `groups/${groupId}/${fileType.toLowerCase()}`;
    const result = await this.storageProvider.upload(file, subfolder);

    const ext = path.extname(file.originalname).toLowerCase().replace('.', '');

    // 5. Persist file metadata
    const dbFile = await this.uploadsRepository.createFile({
      originalName: file.originalname,
      fileName: path.basename(result.storageKey),
      mimeType: file.mimetype,
      extension: ext,
      size: file.size,
      fileType,
      provider: result.provider,
      storageKey: result.storageKey,
      url: result.url,
      uploadedById: uploaderId,
      groupId,
      checksum,
    });

    return {
      id: dbFile.id,
      originalName: dbFile.originalName,
      mimeType: dbFile.mimeType,
      size: Number(dbFile.size),
      fileType: dbFile.fileType,
      provider: dbFile.provider,
      url: dbFile.url,
      status: dbFile.status,
      uploadedById: dbFile.uploadedById,
      groupId: dbFile.groupId,
      createdAt: dbFile.createdAt,
    };
  }

  async listGroupFiles(groupId: string, page = 1, limit = 20) {
    const skip = (page - 1) * limit;
    const { items, total } = await this.uploadsRepository.findByGroup(
      groupId,
      skip,
      limit,
    );

    const data: FileResponseDto[] = items.map((f) => ({
      id: f.id,
      originalName: f.originalName,
      mimeType: f.mimeType,
      size: Number(f.size),
      fileType: f.fileType,
      provider: f.provider,
      url: f.url,
      status: f.status,
      uploadedById: f.uploadedById,
      groupId: f.groupId,
      createdAt: f.createdAt,
    }));

    return {
      data,
      meta: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
        hasNext: page * limit < total,
        hasPrev: page > 1,
      },
    };
  }

  async deleteFile(fileId: string, userId: string) {
    const file = await this.uploadsRepository.findById(fileId);
    if (!file) {
      throw new NotFoundException('File not found');
    }

    if (file.uploadedById !== userId) {
      throw new ForbiddenException('You can only delete files you uploaded');
    }

    await this.storageProvider.delete(file.storageKey);
    await this.uploadsRepository.softDelete(fileId);

    return { message: 'File deleted successfully' };
  }

  private resolveFileType(mimeType: string): FileType {
    if (mimeType.startsWith('image/')) return FileType.IMAGE;
    if (mimeType.startsWith('video/')) return FileType.VIDEO;
    if (mimeType.startsWith('audio/')) return FileType.AUDIO;
    if (
      mimeType.includes('pdf') ||
      mimeType.includes('msword') ||
      mimeType.includes('document')
    ) {
      return FileType.DOCUMENT;
    }
    if (
      mimeType.includes('zip') ||
      mimeType.includes('tar') ||
      mimeType.includes('gzip')
    ) {
      return FileType.ARCHIVE;
    }
    return FileType.OTHER;
  }
}

