import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service.js';
import { VideoStatus, VideoVisibility } from '@prisma/client';

const VIDEO_INCLUDE = {
  videoChannel: {
    select: { id: true, name: true, handle: true, groupId: true },
  },
  uploadedBy: {
    select: {
      id: true,
      username: true,
      profile: { select: { displayName: true, avatarFileId: true } },
    },
  },
  renditions: {
    select: {
      id: true,
      resolution: true,
      height: true,
      width: true,
      bitrate: true,
      url: true,
      isReady: true,
    },
    orderBy: { height: 'asc' as const },
  },
  chapters: {
    select: { id: true, title: true, startTimeMs: true, order: true },
    orderBy: { order: 'asc' as const },
  },
} as const;

@Injectable()
export class VideosRepository {
  constructor(private readonly prisma: PrismaService) {}

  async create(data: {
    videoChannelId: string;
    uploadedById: string;
    title: string;
    slug: string;
    description?: string;
    visibility?: VideoVisibility;
    categories?: string[];
    tags?: string[];
    hashtags?: string[];
    seoTitle?: string;
    seoDescription?: string;
    downloadPermission?: any;
    isDownloadable?: boolean;
  }) {
    return this.prisma.video.create({
      data: {
        videoChannelId: data.videoChannelId,
        uploadedById: data.uploadedById,
        title: data.title,
        slug: data.slug,
        description: data.description,
        visibility: data.visibility ?? VideoVisibility.PRIVATE,
        categories: data.categories ?? [],
        tags: data.tags ?? [],
        hashtags: data.hashtags ?? [],
        seoTitle: data.seoTitle,
        seoDescription: data.seoDescription,
        downloadPermission: data.downloadPermission,
        isDownloadable: data.isDownloadable ?? false,
        status: VideoStatus.UPLOADING,
      },
      include: VIDEO_INCLUDE,
    });
  }

  async findById(id: string) {
    return this.prisma.video.findUnique({
      where: { id, deletedAt: null },
      include: VIDEO_INCLUDE,
    });
  }

  async findBySlug(slug: string) {
    return this.prisma.video.findUnique({
      where: { slug },
      include: VIDEO_INCLUDE,
    });
  }

  async findByChannel(
    videoChannelId: string,
    opts: {
      page?: number;
      limit?: number;
      cursor?: string;
      status?: VideoStatus;
      visibility?: VideoVisibility;
      search?: string;
    },
  ) {
    const limit = opts.limit ?? 20;
    const skip = opts.cursor ? 1 : opts.page ? (opts.page - 1) * limit : 0;

    const where = {
      videoChannelId,
      deletedAt: null,
      ...(opts.status ? { status: opts.status } : {}),
      ...(opts.visibility ? { visibility: opts.visibility } : {}),
      ...(opts.search
        ? {
            OR: [
              {
                title: { contains: opts.search, mode: 'insensitive' as const },
              },
              {
                description: {
                  contains: opts.search,
                  mode: 'insensitive' as const,
                },
              },
            ],
          }
        : {}),
    };

    const videos = await this.prisma.video.findMany({
      where,
      ...(opts.cursor ? { cursor: { id: opts.cursor }, skip: 1 } : { skip }),
      take: limit + 1,
      orderBy: { createdAt: 'desc' },
      include: VIDEO_INCLUDE,
    });

    const total = await this.prisma.video.count({ where });
    const hasMore = videos.length > limit;
    const data = hasMore ? videos.slice(0, limit) : videos;
    const nextCursor = hasMore ? data[data.length - 1].id : undefined;

    return { data, total, nextCursor, hasMore };
  }

  async findPublicVideos(opts: {
    page?: number;
    limit?: number;
    cursor?: string;
    search?: string;
    category?: string;
  }) {
    const limit = opts.limit ?? 20;
    const skip = opts.cursor ? 1 : opts.page ? (opts.page - 1) * limit : 0;

    const where = {
      status: VideoStatus.READY,
      visibility: VideoVisibility.PUBLIC,
      deletedAt: null,
      ...(opts.search
        ? {
            OR: [
              {
                title: { contains: opts.search, mode: 'insensitive' as const },
              },
              { hashtags: { has: opts.search } },
            ],
          }
        : {}),
      ...(opts.category ? { categories: { has: opts.category } } : {}),
    };

    const videos = await this.prisma.video.findMany({
      where,
      ...(opts.cursor ? { cursor: { id: opts.cursor }, skip: 1 } : { skip }),
      take: limit + 1,
      orderBy: { viewsCount: 'desc' },
      include: VIDEO_INCLUDE,
    });

    const total = await this.prisma.video.count({ where });
    const hasMore = videos.length > limit;
    const data = hasMore ? videos.slice(0, limit) : videos;
    const nextCursor = hasMore ? data[data.length - 1].id : undefined;

    return { data, total, nextCursor, hasMore };
  }

  async update(id: string, data: Record<string, any>) {
    return this.prisma.video.update({
      where: { id },
      data,
      include: VIDEO_INCLUDE,
    });
  }

  async softDelete(id: string) {
    return this.prisma.video.update({
      where: { id },
      data: { deletedAt: new Date(), status: VideoStatus.DELETED },
    });
  }

  async updateStatus(id: string, status: VideoStatus) {
    return this.prisma.video.update({ where: { id }, data: { status } });
  }

  async setSourceFile(id: string, fileId: string) {
    return this.prisma.video.update({
      where: { id },
      data: { sourceFileId: fileId, status: VideoStatus.QUEUED },
    });
  }

  async setProcessingResult(
    id: string,
    data: {
      duration?: number;
      width?: number;
      height?: number;
      bitrate?: number;
      videoCodec?: string;
      audioCodec?: string;
      thumbnailUrl?: string;
      hlsUrl?: string;
      status: VideoStatus;
    },
  ) {
    return this.prisma.video.update({ where: { id }, data });
  }

  async createRendition(data: {
    videoId: string;
    resolution: any;
    height: number;
    width: number;
    bitrate: number;
    fileSize: bigint;
    storageKey: string;
    url: string;
    provider: any;
  }) {
    return this.prisma.videoRendition.create({ data });
  }

  async incrementViews(id: string) {
    return this.prisma.video.update({
      where: { id },
      data: { viewsCount: { increment: 1 } },
    });
  }

  async updateLikeCounts(id: string) {
    const [likes, dislikes] = await this.prisma.$transaction([
      this.prisma.videoLike.count({ where: { videoId: id, isLike: true } }),
      this.prisma.videoLike.count({ where: { videoId: id, isLike: false } }),
    ]);
    return this.prisma.video.update({
      where: { id },
      data: { likesCount: likes, dislikesCount: dislikes },
    });
  }

  async upsertLike(userId: string, videoId: string, isLike: boolean) {
    return this.prisma.videoLike.upsert({
      where: { userId_videoId: { userId, videoId } },
      create: { userId, videoId, isLike },
      update: { isLike },
    });
  }

  async removeLike(userId: string, videoId: string) {
    return this.prisma.videoLike.deleteMany({ where: { userId, videoId } });
  }

  async getUserLike(userId: string, videoId: string) {
    return this.prisma.videoLike.findUnique({
      where: { userId_videoId: { userId, videoId } },
    });
  }

  async upsertWatchProgress(data: {
    userId: string;
    videoId: string;
    watchedSeconds: number;
    watchedPercent: number;
    isCompleted: boolean;
  }) {
    return this.prisma.videoWatchHistory.upsert({
      where: { userId_videoId: { userId: data.userId, videoId: data.videoId } },
      create: {
        userId: data.userId,
        videoId: data.videoId,
        watchedSeconds: data.watchedSeconds,
        watchedPercent: data.watchedPercent,
        isCompleted: data.isCompleted,
      },
      update: {
        watchedSeconds: data.watchedSeconds,
        watchedPercent: data.watchedPercent,
        isCompleted: data.isCompleted,
        watchedAt: new Date(),
      },
    });
  }

  async getWatchHistory(userId: string, page: number, limit: number) {
    const skip = (page - 1) * limit;
    const [data, total] = await this.prisma.$transaction([
      this.prisma.videoWatchHistory.findMany({
        where: { userId },
        include: {
          video: {
            select: {
              id: true,
              title: true,
              slug: true,
              thumbnailUrl: true,
              duration: true,
              status: true,
              visibility: true,
              videoChannel: { select: { id: true, name: true, handle: true } },
            },
          },
        },
        skip,
        take: limit,
        orderBy: { watchedAt: 'desc' },
      }),
      this.prisma.videoWatchHistory.count({ where: { userId } }),
    ]);
    return { data, total };
  }

  async getWatchProgress(userId: string, videoId: string) {
    return this.prisma.videoWatchHistory.findUnique({
      where: { userId_videoId: { userId, videoId } },
    });
  }

  async upsertBookmark(userId: string, videoId: string, note?: string) {
    return this.prisma.videoBookmark.upsert({
      where: { userId_videoId: { userId, videoId } },
      create: { userId, videoId, note },
      update: { note },
    });
  }

  async removeBookmark(userId: string, videoId: string) {
    return this.prisma.videoBookmark.delete({
      where: { userId_videoId: { userId, videoId } },
    });
  }

  async getBookmarks(userId: string, page: number, limit: number) {
    const skip = (page - 1) * limit;
    const [data, total] = await this.prisma.$transaction([
      this.prisma.videoBookmark.findMany({
        where: { userId },
        include: {
          video: {
            select: {
              id: true,
              title: true,
              slug: true,
              thumbnailUrl: true,
              duration: true,
              status: true,
              videoChannel: { select: { id: true, name: true, handle: true } },
            },
          },
        },
        skip,
        take: limit,
        orderBy: { createdAt: 'desc' },
      }),
      this.prisma.videoBookmark.count({ where: { userId } }),
    ]);
    return { data, total };
  }

  async getTrending(limit = 20) {
    return this.prisma.video.findMany({
      where: {
        status: VideoStatus.READY,
        visibility: VideoVisibility.PUBLIC,
        deletedAt: null,
        publishedAt: { gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000) },
      },
      orderBy: [{ viewsCount: 'desc' }, { likesCount: 'desc' }],
      take: limit,
      include: VIDEO_INCLUDE,
    });
  }

  async getRecommended(userId: string, videoId: string, limit = 10) {
    // Get the video's categories and tags for recommendation
    const video = await this.prisma.video.findUnique({
      where: { id: videoId },
      select: { categories: true, tags: true, videoChannelId: true },
    });

    if (!video) return [];

    return this.prisma.video.findMany({
      where: {
        status: VideoStatus.READY,
        visibility: VideoVisibility.PUBLIC,
        deletedAt: null,
        id: { not: videoId },
        OR: [
          { categories: { hasSome: video.categories } },
          { tags: { hasSome: video.tags } },
          { videoChannelId: video.videoChannelId },
        ],
      },
      orderBy: { viewsCount: 'desc' },
      take: limit,
      include: VIDEO_INCLUDE,
    });
  }

  async reportVideo(data: {
    videoId: string;
    userId: string;
    reason: any;
    details?: string;
  }) {
    return this.prisma.videoReport.upsert({
      where: { videoId_userId: { videoId: data.videoId, userId: data.userId } },
      create: data,
      update: { reason: data.reason, details: data.details },
    });
  }
}

// src/modules/videos/videos.service.ts
import {
  BadRequestException,
  ForbiddenException,
  Injectable,
  NotFoundException,
  Logger,
} from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';
import { PrismaService } from '../../prisma/prisma.service.js';
import { VideosRepository } from './videos.repository.js';
import { UploadVideoDto } from './dto/upload-video.dto.js';
import { UpdateVideoDto } from './dto/update-video.dto.js';
import { VideoStatus, VideoVisibility, GroupRole } from '@prisma/client';
import { AppRole } from '../../common/constants/roles.js';
import { v4 as uuidv4 } from 'uuid';
import { VIDEO_PROCESSING_QUEUE } from '../video-processing/video-processing.processor.js';

@Injectable()
export class VideosService {
  private readonly logger = new Logger(VideosService.name);

  constructor(
    private readonly repo: VideosRepository,
    private readonly prisma: PrismaService,
    @InjectQueue(VIDEO_PROCESSING_QUEUE) private readonly videoQueue: Queue,
  ) {}

  private generateSlug(title: string): string {
    const base = title
      .toLowerCase()
      .replace(/[^a-z0-9\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .substring(0, 80);
    return `${base}-${uuidv4().substring(0, 8)}`;
  }

  private async verifyChannelUploadPermission(
    videoChannelId: string,
    userId: string,
  ): Promise<{ groupId: string; channelId: string }> {
    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      include: { role: true },
    });
    if (!user) throw new NotFoundException('User not found');

    // SUPER_ADMIN bypasses all checks
    if (
      (user.role.name as AppRole) === AppRole.SUPER_ADMIN ||
      (user.role.name as AppRole) === AppRole.ADMIN
    ) {
      const channel = await this.prisma.videoChannel.findUnique({
        where: { id: videoChannelId, deletedAt: null },
        select: { id: true, groupId: true },
      });
      if (!channel) throw new NotFoundException('Video channel not found');
      return { groupId: channel.groupId, channelId: channel.id };
    }

    const channel = await this.prisma.videoChannel.findUnique({
      where: { id: videoChannelId, deletedAt: null },
      select: {
        id: true,
        groupId: true,
        uploadPermission: true,
        group: { select: { id: true, status: true } },
      },
    });

    if (!channel) throw new NotFoundException('Video channel not found');
    if (channel.group.status !== 'ACTIVE') {
      throw new ForbiddenException('Group is not active');
    }

    const membership = await this.prisma.groupMember.findUnique({
      where: {
        groupId_userId: { groupId: channel.groupId, userId },
        removedAt: null,
      },
      select: { role: true },
    });

    if (!membership)
      throw new ForbiddenException('You are not a member of this group');

    const roleHierarchy: Record<string, number> = {
      GROUP_ADMIN: 4,
      MODERATOR: 3,
      MEMBER: 2,
      GUEST: 1,
    };

    const userLevel = roleHierarchy[membership.role] ?? 0;
    const requiredLevel = roleHierarchy[channel.uploadPermission] ?? 2;

    if (userLevel < requiredLevel) {
      throw new ForbiddenException(
        `Upload requires at least ${channel.uploadPermission} role in this channel`,
      );
    }

    return { groupId: channel.groupId, channelId: channel.id };
  }

  /**
   * Phase 1 of video upload: Create the video record and return ID.
   * The actual file is uploaded separately via the uploads endpoint.
   */
  async initiateUpload(
    videoChannelId: string,
    userId: string,
    dto: UploadVideoDto,
  ) {
    await this.verifyChannelUploadPermission(videoChannelId, userId);

    const slug = this.generateSlug(dto.title);

    const video = await this.repo.create({
      videoChannelId,
      uploadedById: userId,
      title: dto.title,
      slug,
      description: dto.description,
      visibility: dto.visibility,
      categories: dto.categories,
      tags: dto.tags,
      hashtags: dto.hashtags,
      seoTitle: dto.seoTitle,
      seoDescription: dto.seoDescription,
      downloadPermission: dto.downloadPermission,
      isDownloadable: dto.isDownloadable,
    });

    return video;
  }

  /**
   * Called after the source file has been uploaded.
   * Associates the file with the video and queues processing.
   */
  async attachSourceFile(videoId: string, fileId: string, userId: string) {
    const video = await this.repo.findById(videoId);
    if (!video) throw new NotFoundException('Video not found');

    if (video.uploadedById !== userId) {
      const user = await this.prisma.user.findUnique({
        where: { id: userId },
        include: { role: true },
      });
      if (
        !user ||
        ((user.role.name as AppRole) !== AppRole.SUPER_ADMIN &&
          (user.role.name as AppRole) !== AppRole.ADMIN)
      ) {
        throw new ForbiddenException(
          'Only the video uploader can attach files',
        );
      }
    }

    if (video.status !== VideoStatus.UPLOADING) {
      throw new BadRequestException('Video is not in UPLOADING state');
    }

    // 1. Update DB — sets status → QUEUED and links source file
    const updated = await this.repo.setSourceFile(videoId, fileId);

    // 2. Resolve source file path from the attached file record
    const fileRecord = await this.prisma.file.findUnique({
      where: { id: fileId },
      select: { storageKey: true },
    });
    const sourceFilePath =
      fileRecord?.storageKey ?? `videos/${videoId}/raw.mp4`;

    // 3. Enqueue BullMQ transcode job
    await this.videoQueue.add(
      'transcode',
      { videoId, sourceFilePath, storageKey: sourceFilePath },
      {
        attempts: 3,
        backoff: { type: 'exponential', delay: 5000 },
        removeOnComplete: 100,
        removeOnFail: 50,
      },
    );

    this.logger.log(
      `Video [${videoId}] queued for transcoding (file: ${sourceFilePath})`,
    );
    return updated;
  }

  async findById(id: string, userId?: string) {
    const video = await this.repo.findById(id);
    if (!video) throw new NotFoundException('Video not found');

    // Increment view count for READY public videos
    if (video.status === VideoStatus.READY && userId) {
      void this.repo.incrementViews(id);
    }

    return this.mapVideoToDto(video);
  }

  async findBySlug(slug: string, userId?: string) {
    const video = await this.repo.findBySlug(slug);
    if (!video) throw new NotFoundException('Video not found');

    if (video.status === VideoStatus.READY && userId) {
      void this.repo.incrementViews(video.id);
    }

    return this.mapVideoToDto(video);
  }

  async findByChannel(
    videoChannelId: string,
    userId: string,
    opts: {
      page?: number;
      limit?: number;
      cursor?: string;
      status?: VideoStatus;
      search?: string;
    },
  ) {
    // For non-admins, restrict to READY + PUBLIC/GROUP_ONLY
    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      include: { role: true },
    });
    const isAdmin =
      user?.role.name === AppRole.SUPER_ADMIN ||
      user?.role.name === AppRole.ADMIN;

    const result = await this.repo.findByChannel(videoChannelId, {
      ...opts,
      ...(isAdmin
        ? {}
        : {
            status: VideoStatus.READY,
            visibility: VideoVisibility.PUBLIC,
          }),
    });

    return {
      ...result,
      data: result.data.map((v) => this.mapVideoToDto(v)),
    };
  }

  async update(id: string, userId: string, dto: UpdateVideoDto) {
    const video = await this.repo.findById(id);
    if (!video) throw new NotFoundException('Video not found');

    const canEdit = await this.canModifyVideo(video, userId);
    if (!canEdit)
      throw new ForbiddenException(
        'Insufficient permissions to edit this video',
      );

    const data: Record<string, any> = { ...dto };
    if (dto.scheduledAt) {
      data.scheduledAt = new Date(dto.scheduledAt);
      data.visibility = VideoVisibility.SCHEDULED;
    }

    return this.mapVideoToDto(await this.repo.update(id, data));
  }

  async publish(id: string, userId: string) {
    const video = await this.repo.findById(id);
    if (!video) throw new NotFoundException('Video not found');
    if (video.status !== VideoStatus.READY) {
      throw new BadRequestException('Video must be READY before publishing');
    }
    const canEdit = await this.canModifyVideo(video, userId);
    if (!canEdit) throw new ForbiddenException('Insufficient permissions');

    return this.mapVideoToDto(
      await this.repo.update(id, {
        visibility: VideoVisibility.PUBLIC,
        publishedAt: new Date(),
      }),
    );
  }

  async delete(id: string, userId: string) {
    const video = await this.repo.findById(id);
    if (!video) throw new NotFoundException('Video not found');

    const canEdit = await this.canModifyVideo(video, userId);
    if (!canEdit)
      throw new ForbiddenException(
        'Insufficient permissions to delete this video',
      );

    await this.repo.softDelete(id);
    return { message: 'Video deleted successfully' };
  }

  async likeVideo(videoId: string, userId: string, isLike: boolean) {
    const video = await this.repo.findById(videoId);
    if (!video) throw new NotFoundException('Video not found');

    await this.repo.upsertLike(userId, videoId, isLike);
    await this.repo.updateLikeCounts(videoId);
    return {
      message: isLike ? 'Video liked' : 'Video disliked',
      videoId,
    };
  }

  async removeLike(videoId: string, userId: string) {
    const video = await this.repo.findById(videoId);
    if (!video) throw new NotFoundException('Video not found');

    await this.repo.removeLike(userId, videoId);
    await this.repo.updateLikeCounts(videoId);
    return { message: 'Reaction removed', videoId };
  }

  async getUserLikeStatus(videoId: string, userId: string) {
    const like = await this.repo.getUserLike(userId, videoId);
    return { liked: !!like && like.isLike, disliked: !!like && !like.isLike };
  }

  async updateWatchProgress(
    videoId: string,
    userId: string,
    watchedSeconds: number,
  ) {
    const video = await this.repo.findById(videoId);
    if (!video) throw new NotFoundException('Video not found');

    const duration = video.duration ?? 0;
    const watchedPercent =
      duration > 0 ? Math.min((watchedSeconds / duration) * 100, 100) : 0;
    const isCompleted = watchedPercent >= 90;

    return this.repo.upsertWatchProgress({
      userId,
      videoId,
      watchedSeconds,
      watchedPercent,
      isCompleted,
    });
  }

  async getWatchHistory(userId: string, page = 1, limit = 20) {
    return this.repo.getWatchHistory(userId, page, limit);
  }

  async getWatchProgress(videoId: string, userId: string) {
    return this.repo.getWatchProgress(userId, videoId);
  }

  async bookmarkVideo(videoId: string, userId: string, note?: string) {
    const video = await this.repo.findById(videoId);
    if (!video) throw new NotFoundException('Video not found');

    await this.repo.upsertBookmark(userId, videoId, note);
    await this.repo.update(videoId, { bookmarksCount: { increment: 1 } });
    return { message: 'Video bookmarked', videoId };
  }

  async removeBookmark(videoId: string, userId: string) {
    await this.repo.removeBookmark(userId, videoId);
    return { message: 'Bookmark removed', videoId };
  }

  async getBookmarks(userId: string, page = 1, limit = 20) {
    return this.repo.getBookmarks(userId, page, limit);
  }

  async getTrending(limit = 20) {
    const videos = await this.repo.getTrending(limit);
    return videos.map((v) => this.mapVideoToDto(v));
  }

  async getRecommended(videoId: string, userId: string, limit = 10) {
    const videos = await this.repo.getRecommended(userId, videoId, limit);
    return videos.map((v) => this.mapVideoToDto(v));
  }

  async searchVideos(opts: {
    search?: string;
    category?: string;
    page?: number;
    limit?: number;
    cursor?: string;
  }) {
    const result = await this.repo.findPublicVideos(opts);
    return { ...result, data: result.data.map((v) => this.mapVideoToDto(v)) };
  }

  async reportVideo(
    videoId: string,
    userId: string,
    reason: any,
    details?: string,
  ) {
    const video = await this.repo.findById(videoId);
    if (!video) throw new NotFoundException('Video not found');

    return this.repo.reportVideo({ videoId, userId, reason, details });
  }

  private async canModifyVideo(video: any, userId: string): Promise<boolean> {
    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      include: { role: true },
    });
    if (!user) return false;
    if (
      (user.role.name as AppRole) === AppRole.SUPER_ADMIN ||
      (user.role.name as AppRole) === AppRole.ADMIN
    )
      return true;
    if (video.uploadedById === userId) return true;

    // Check group MODERATOR or higher
    const membership = await this.prisma.groupMember.findUnique({
      where: {
        groupId_userId: { groupId: video.videoChannel.groupId, userId },
        removedAt: null,
      },
      select: { role: true },
    });
    return (
      membership?.role === GroupRole.GROUP_ADMIN ||
      membership?.role === GroupRole.MODERATOR
    );
  }

  private mapVideoToDto(video: any) {
    return {
      ...video,
      viewsCount: video.viewsCount?.toString() ?? '0',
    };
  }
}
